  str_guide_warn_11200102 = "In No Man's Land, we'll face a series of difficult challenges.",
  str_guide_warn_11200103 = "Empty Shell Casings obtained by completing event stages and spending Prism can be used to redeem various rewards from the Supply Depot.",
  str_guide_warn_11200104 = "In Street Errands, we will further explore the town and collect information and news in the streets.",
  str_guide_warn_11200105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11200106 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11200107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11200203 = "This is a dangerous and rewarding quest. Let's go now!",
  str_guide_warn_11200204 = "The central elevator can take us straight to the depths, but it's filled with harmful gases below, so it cannot be explored for now.",
  str_guide_warn_11200205 = "Here is a list of rewards from Illumina. The deeper we venture, the more rewards we'll get.",
  str_guide_warn_11200206 = "Anyway, let's see if we can find a way to remove the harmful gases!",
  str_guide_warn_11200207 = "The Eclipsites have seized all the Ventilators here. Activate all Ventilators to remove the harmful gases and continue exploring the next floor.",
  str_guide_warn_11200208 = "You will need to station 5 Aurorians at each Ventilator to activate it. The Ventilators will not activate if you withdraw the Aurorians before the purification is completed on the floor.",
  str_guide_warn_11200209 = "Activate all the Ventilators by stationing several teams of different Aurorians to continue exploring.",
