  str_guide_warn_11400103 = "Everyone in Cloud Gardens seems to be excited about holding a fishing competition. Check out the new Cloud Gardens Feats event: An Extraordinary Catch!",
  str_guide_warn_11400104 = "Complete challenges with your new friends to get Lumamber rewards!",
  str_guide_warn_11400105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11400106 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11400107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11500101 = "The Starry Adventure: Heaven-Shaking Melody event has started! We're going to hold a one-of-a-kind concert together with Goldie!",
  str_guide_warn_11500102 = "In Dreamy Nostalgia, we'll face a series of difficult challenges.",
  str_guide_warn_11500103 = "Goldie Merch obtained by completing event stages and spending Prism can be used to redeem various rewards from Brandy's Tabloids.",
  str_guide_warn_11500104 = "A mysterious Eclipsite lair has appeared near the Secret Territory. Navigators can overcome the obstacle by learning Talent Mastery Skills and using relics to earn Lumamber!",
  str_guide_warn_11500105 = "In Starlit Agency, the Navigator will become Goldie's agent. Provide her with training and organize activities to ultimately send her onto the concert stage!",
  str_guide_warn_11500106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11500107 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11500108 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11500201 = "Let's get started, Navigator. This is the Starlit Agency, where we will train idols and host events to eventually get them up on the stage.",
  str_guide_warn_11500202 = "The agency has set some objectives for us. Rewards are available after completion. Memories from training will also be logged here.",
  str_guide_warn_11500203 = "If you're not satisfied with the training, you can go back to select key moments to make a different decision.",
  str_guide_warn_11500204 = "Time to start training, Navigator!",
  str_guide_warn_11500301 = "This is the countdown until the concert. 13 days left! You've got your work cut out for you.",
  str_guide_warn_11500302 = "But we must gain 150,000 fans before we can hold a concert.",
  str_guide_warn_11500303 = "Being an idol means lots of training. There are three training modes available. Be sure you stay calm when the paparazzi show up!",
  str_guide_warn_11500304 = "Here are my idol skills. The training modes will improve them.",
  str_guide_warn_11500305 = "Holding events can help us gain more fans so we can reach the requirement for the concert!",
  str_guide_warn_11500306 = "Here's this week's to-do list, you can use it as a reference for scheduling. Talk to people during the training, and you just might get something out of it.",
  str_guide_warn_11500307 = "The rest of the information is in the Producer's Handbook. Consult it whenever you need something!",
  str_guide_warn_11500402 = "Go to the Lair to start the challenge. In addition to Lumamber, players will also earn Talent Mastery EXP to increase their Talent Levels and earn Talent Mastery Points to become more powerful.",
  str_guide_warn_11500403 = "This is where you can find Lair Reward quests. Completing quests will also earn you Talent Mastery Points.",
  str_guide_warn_11500404 = "Spend Talent Mastery Points to unlock Talent Mastery Skills, Special Caelestite Gear, and Relics to make Lair Challenges easier!",
  str_guide_warn_11500405 = "Every day, different trial Aurorians will be available to use in Lair Challenges.",
  str_guide_warn_11500406 = "You can find more information about the Lair here. Feel free to browse it at any time.",
  str_guide_warn_11500601 = "Earn enough Talent Mastery EXP to increase your Talent Level and earn Talent Mastery Points.",
  str_guide_warn_11500602 = "Spend Talent Mastery Points to activate Talent Masteries like Special Caelestite Gear to boost your team.",
  str_guide_warn_11500603 = "After spending enough Talent Mastery Points, powerful Relics may appear at random during Lair Challenges.",
  str_guide_warn_11500604 = "You can equip Special Caelestite Gear here. They provide additional powerful skills during the challenge.",
  str_guide_warn_11500605 = "If you want to edit your Talent Masteries, you can reset activated Talent Masteries and Talent Mastery Points spent at no cost.",
  str_guide_warn_11500701 = "Tap here to view the Aurorians in your team.",
  str_guide_warn_11600101 = "The Etched Upon the Ocean event has begun! Join a cast of new friends from Longzhou as we search for lost treasure and uncover mysterious secrets in The Homecoming!",
  str_guide_warn_11600102 = "In Lost Ship At Sea, we'll face a series of difficult challenges.",
  str_guide_warn_11600103 = "Lin Guild Promissory Notes obtained by completing event stages and spending Prism can be used to redeem various rewards from The Docks.",
  str_guide_warn_11600104 = "During the Spring Festival, the people of Longzhou prepare a sumptuous feast called the Unity Dinner. Help Dantang find recipes to make tasty dishes to obtain various rewards, including Lumamber!",
  str_guide_warn_11600105 = "An anonymous guestbook has appeared on set. It will gradually fill with anonymous comments. Read these messages to get new movie scripts!",
  str_guide_warn_11600106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11600107 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11600108 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11700101 = "The Fragmentary Vow event has begun! Embark on an adventure with your new friends from the Courier Union in the Mooncrown Pilgrimage.",
  str_guide_warn_11700102 = "In the Feather Seal Crisis, we'll face a series of difficult challenges.",
  str_guide_warn_11700103 = "Rare Feathers obtained by completing event stages and spending Prism can be exchanged for various rewards at the Courier Express.",
  str_guide_warn_11700104 = "In Sweet Delivery, you can experience life working at a Courier Union post and solve the Navigator's endless best wishes crisis at the same time!",
  str_guide_warn_11700105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11700106 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11700107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11700201 = "This is your currently received order information. Tap an avatar to switch orders.",
  str_guide_warn_11700202 = "Let's finish Lilica's order first. She needs clothes, bread, and wine.",
  str_guide_warn_11700203 = "On the right, you can find the complete goods list.",
  str_guide_warn_11700204 = "Let's put some bread into the package!",
  str_guide_warn_11700205 = "While tapping and holding to drag the goods, you can also tap buttons to rotate (R key) and flip (T key).",
  str_guide_warn_117002051 = "While tapping and holding to drag the goods, you can also tap buttons to rotate and flip.",
  str_guide_warn_11700206 = "After all items on order have been placed in the package, remember to tap the packaging button to send it. If not all of the items have been placed in the package, the final order's completion progress will be affected.",
  str_guide_warn_11700207 = "Tap here to pause packaging.",
  str_guide_warn_11700208 = "Now that you know all about the workflow process, let's continue packing!",
  str_guide_warn_11800101 = "The Confess Before the Gavel Strikes event has begun! Embark on an adventure with everyone in the Hall of Justice during Heartfelt Admissions.",
  str_guide_warn_11800102 = "In When the Flowers Wither, we'll face a series of difficult challenges.",
  str_guide_warn_11800103 = "Plaster Fragments obtained by completing event stages and spending Prism can be used to redeem various rewards from the Evidence Collection.",
  str_guide_warn_11800104 = "During the Love on Trial event, you will serve as an assistant judge, hearing out the cases at hand and investigating the truth with the members of the Romance Division.",
  str_guide_warn_11800105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11800106 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11800107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11800201 = "Not everyone gets to work in the Hall of Justice. I would definitely make the most of this opportunity if I were you! Tap here to go to the Hall of Justice and see what cases are waiting for you.",
  str_guide_warn_11800202 = "Cases can have different endings depending on how the trial goes. If you get stuck while investigating, you can go to Case Record and choose a corresponding story selection point to make different decisions.",
  str_guide_warn_11800203 = "You'll definitely be rewarded for your hard work. Complete stories to unlock endings and meet various conditions to claim badges and rewards here!",
  str_guide_warn_11800204 = "I've written down all the details here. Remember to read them again if there's anything you still don't get.",
  str_guide_warn_11800301 = "Wow! You've already learned how to collect evidence so quickly? All this evidence will come into use when it's time to present the evidence.",
  str_guide_warn_11800401 = "That's right. It's time to present the evidence! The evidence you've collected will be listed in the evidence list. Don't forget to tap them to view more detailed information.",
  str_guide_warn_11800402 = [[
Presenting the wrong evidence can affect your Competence and the result of the trial!
Let's try to select the correct piece of evidence according to Angel's question. Tap here to strike back!]],
  str_guide_warn_11800501 = "The Judge's Notebook is a symbol of a judge's identity. Are you curious about its contents?",
  str_guide_warn_11800502 = "Oh! The evidence and details you collect are recorded here. That makes it really convenient to check everything.",
  str_guide_warn_11800503 = "It's also very important to foster stronger Rapport with your colleagues as the Rapport between you and your colleagues can also affect the direction of the trial. Good luck!",
  str_guide_warn_11800601 = "Let me introduce the basic rules of the game! You need to control your character, fighting through all the stages until you make it all the way to the final boss—Gronkenstein Ruu!",
  str_guide_warn_11800602 = "You can tap this button to switch characters, but they're all exactly the same in terms of actual gameplay—don't you judge that!",
  str_guide_warn_11800603 = "If there's anything you still don't understand, you can check out the documentation here.",
  str_guide_warn_11800701 = "Stages will unlock gradually over time. Let's try the first stage!",
  str_guide_warn_11800702 = "As long as you complete the first target of each stage, you'll clear it! You can also go for all of the targets if you want!",
  str_guide_warn_11800703 = "Let's get ready to rumble!",
  str_guide_warn_11800801 = "This is it! You need to keep your character moving forward and try not to let the Eclipsites get you! Make it to the target!",
  str_guide_warn_11800802 = "There's a normal Eclipsite up ahead! Seize the perfect moment to jump on its head, then it'll be game over for that normie noob!",
  str_guide_warn_11800803 = "Now! Tap the Jump button!",
  str_guide_warn_118008031 = "Now! Tap the Jump button (T)!",
  str_guide_warn_11800804 = "Not bad! You're a natural-born gamer!",
  str_guide_warn_11800805 = "Next, we're gonna have to deal with a flying Eclipsite. After you bounce off, you can attack an Eclipsite at a higher position using a double jump!",
  str_guide_warn_11800806 = "Now, tap Jump!",
  str_guide_warn_11800807 = "Tap Jump again to use your double jump attack!",
  str_guide_warn_11800808 = "You have now officially mastered the basic controls of the game! Try clearing this stage by yourself!",
  str_guide_warn_11800901 = "Navigator, a little birdie tells me you've been complaining about the first stage being way too easy for you!",
  str_guide_warn_11800902 = "Well, don't worry—I've got even more difficult new monsters waiting for you! These helmet-headed Eclipsites need to be jumped on twice before you can count them out!",
  str_guide_warn_11800903 = "Tap Jump and get rid of that helmet!",
  str_guide_warn_11800904 = "Tap Dive while in the air to quickly dive down and wipe out the enemy down below!",
  str_guide_warn_118009041 = "Hit Dive (R) while in the air to quickly dive down and wipe out the enemy down below!",
  str_guide_warn_11800905 = "Tip: Diving is not only good for attacking enemies but also makes you bounce higher, so you can reach enemies way up in the sky!",
  str_guide_warn_11800906 = "This is the last little bit of advice I'm gonna give you! These thorny Eclipsites can't be stomped on, so when you see them, avoid them by jumping up! Well, it's all up to you now, Navigator! Good luck!",
  str_guide_warn_11801001 = "Eheheheh! Finally, it's time for me to take center stage! Meet the final boss—Gronkenstein Ruu!",
  str_guide_warn_11801101 = "This is one of my love shells. Promise me you won't use Dive or Double Jump to bust it apart. Otherwise, I won't be able to beat you!",
  str_guide_warn_11801201 = "Yikes! You actually deflected my shell and made it hit me instead!?",
  str_guide_warn_11801202 = "I only have so much HP... If you keep hitting me with shells, I'll... Hey, why are you so good at this, Navigator!? Fine, then! Bring it on!",
  str_guide_warn_11900101 = "The Phantom of the Fire event has begun! Prepare to investigate the mysterious case and explore the truth behind it with your friends at Umbraton in Manhunt: The Blue Flame!",
  str_guide_warn_11900102 = "In Dark Alley Encounters, we'll face a series of difficult challenges.",
  str_guide_warn_11900103 = "Case Records obtained by completing event stages and spending Prism can be used to redeem various rewards from Search & Seizure.",
  str_guide_warn_11900104 = "In the Midnight Scribbles mystery mode, we'll explore the secrets of the orphanage with young Hati!",
  str_guide_warn_11900105 = "Crash & Burn is back for a limited time! Gear up to experience this unique gameplay!",
  str_guide_warn_11900106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_11900107 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_11900108 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_11900201 = "Welcome to Midnight Scribbles! Let's revisit our past experiences in the orphanage together!",
  str_guide_warn_11900202 = "Tap Pick Up Crayon to start!",
  str_guide_warn_11900203 = "If you have already started on an adventure down memory lane, tap here to continue your journey!",
  str_guide_warn_11900204 = "Quests and rewards will be displayed in the album, and you can also see the endings you've achieved!",
  str_guide_warn_11900205 = "If there's anything you still don't understand, you can check out the information here.",
  str_guide_warn_11900301 = "This is a map of the orphanage We'll need to explore everywhere to find inspiration!",
  str_guide_warn_11900302 = "The inspiration you find will be displayed here. They'll come in handy later!",
  str_guide_warn_11900303 = "Let's say hi to Miss Childminder!",
  str_guide_warn_11900304 = "Let's ask Miss Childminder about this place!",
  str_guide_warn_11900401 = "Are you ready to talk to Miss Childminder?",
  str_guide_warn_11900402 = "Here is a list of questions you can ask. Some of them can be asked directly, while others can only be asked after you find certain inspirations!",
  str_guide_warn_11900403 = "Ask her questions about this place!",
  str_guide_warn_11900404 = "Keep asking questions while you explore to find inspiration! You'll be able to ask more questions once you find more inspiration!",
  str_guide_warn_11900501 = "It's so messy here. Let's investigate everything carefully!",
  str_guide_warn_11900502 = "It is shown here that there are many suspicious objects in this room!",
  str_guide_warn_11900503 = "It seems that there are no clues. Let's focus on observing first.",
  str_guide_warn_11900504 = "There's a pair of strange gloves here. Get closer and inspect it!",
  str_guide_warn_11900601 = "Let's go over the inspiration we've found and recap today's events first!",
  str_guide_warn_11900602 = "To solve this mystery, we'll need three pieces of inspiration to get the answer.",
  str_guide_warn_11900603 = "This is all the inspiration you have. You need to choose the correct ones!",
  str_guide_warn_11900604 = "Firstly, about this place... It seems to be a home full of love and affection?",
  str_guide_warn_11900605 = "After that, it's obvious that children are living with us here. There are a lot of children in the orphanage!",
  str_guide_warn_11900606 = "Finally, are we good or bad? Although some of us are nice, there also seems to be some bad guys here... We'll need to identify them all carefully.",
  str_guide_warn_11900607 = "Try to sort through your inspiration!",
  str_guide_warn_11900608 = "Success! So that's what the situation is like at the orphanage!",
  str_guide_name1 = "Signed by...",
  str_guide_name2 = "Please type your nickname",
  str_guide_name3 = "Confirm",
  str_guide_name4 = "Your nickname does not have to be your real name, and cannot include special characters (max 14 characters)",
  str_guide_create_no_name = "Please create your nickname first",
  str_guide_ROLE_ERROR_DIRTY_NICK = "Contains forbidden words",
  str_guide_ROLE_ERROR_CHANGE_NICK_INVALID = "Special characters cannot be used",
  str_guide_ROLE_ERROR_CHANGE_NICK_LIMIT = "Maximum nickname length is 14 characters",
  str_guide_ROLE_ERROR_CHANGE_NICK_REPEAT = "You already have a nickname",
  str_guide_ROLE_ERROR_CHANGE_NICK_SPE = "Special characters cannot be used",
  str_guide_ROLE_ERROR_DUPLICATE_NICK = "Duplicate nickname with other players",
  str_guide_ROLE_ERROR_NEWSIGN_THE_SAME_AS_OLD = "No change in the new signature",
  str_guide_ROLE_ERROR_NEWNAME_THE_SAME_AS_OLD = "No change in the new nickname",
  str_guide_moren_name = "Navigator",
  str_guide_team_limit_4001050 = "This adventure requires Ms. Blanc to be present. Please tap on the card above to change deployed Aurorian.",
  str_guide_circle_click = "Tap anywhere to continue",
  str_guide_circle_1_Lt = "The Auto Defense System (ADS) is the legacy of the ancient era. It's both powerful and functions automatically!",
  str_guide_circle_1_LtT = "Auto Defense System (ADS)",
  str_guide_circle_1_Rt = "The ADS will automatically rotate once each round. Perhaps these are the old settings from ancient times...",
  str_guide_circle_1_RtT = "Movement Rules",
  str_guide_circle_1_Rb = "The ADS will deal damage to any target within three tiles in front of it.",
  str_guide_circle_1_RbT = "Damage Range",
  str_guide_circle_2_Lt = "Crusher is a common, large Eclipsite that possesses uncommonly high ATK and HP.",
  str_guide_circle_2_LtT = "Crusher",
  str_guide_circle_2_Lb = "Large body type means that it will take multi-tile damage. Use the connection to reach the surrounding tiles as much as possible!",
  str_guide_circle_2_LbT = "Important Tips",
  str_guide_circle_3_Lb = "It has high attack damage and is very difficult to clear within a short period of time. Make sure you recover HP in time when encountering this Eclipsite.",
  str_guide_circle_3_LbT = "Important Tips",
  str_guide_circle_3_Lt = "An Eclipsite with Ranged Attack abilities that deals damage to a single unit in its row or column.",
  str_guide_circle_3_LtT = "Prober",
  str_guide_circle_4_Lt = "A unique Eclipsite that summons a Dretcher to the battlefield every round, up to a maximum of 5 Dretchers.",
  str_guide_circle_4_LtT = "Brood Eclipsite - Evil Eye",
  str_guide_circle_4_Rt = "Evil Eye cannot deal damage on its own and is safe to approach.",
  str_guide_circle_4_RtT = "Damage Range",
  str_guide_circle_4_Rb = "If you can't defeat it promptly, it will result in an unpredictable battle, so watch out!",
  str_guide_circle_4_RbT = "Important Tips",
  str_guide_circle_5_Rt = "The Escape Point is not activated and hence unavailable. Eliminate the Eclipsites to unlock it.",
  str_guide_circle_5_RtT = "Escape Point",
  str_guide_circle_6_Rt = "The escape point has been unlocked. Let's hurry and escape from the battlefield!",
  str_guide_circle_6_RtT = "Unlocked",
  str_guide_circle_7_Rb = "Abyssal terrain will hinder movements. Beware of the Eclipsites hiding behind the Abyssal terrain.",
  str_guide_circle_7_RbT = "Abyssal terrain",
  ["str_guide_circle_2-1_Lt"] = "A sneaky Eclipsite that likes to mount high-speed ambushes.",
  ["str_guide_circle_2-1_LtT"] = "High-Speed Eclipsite - Sprint",
  ["str_guide_circle_2-1_Lb"] = "Due to its huge movement range, it's easy for it to sneak up on you, so watch out!",
  ["str_guide_circle_2-1_LbT"] = "Attack Range",
  ["str_guide_circle_2-2_Lt"] = "Said to be a Light Crystal that appeared after the ancient cataclysm. Can summon dangerous meteorites.",
  ["str_guide_circle_2-2_LtT"] = "Light Crystal - Meteorite",
  ["str_guide_circle_2-2_Rt"] = "Deals damage equivalent to a percentage of Max HP to a single enemy. Very effective.",
  ["str_guide_circle_2-2_RtT"] = "Special Effects",
  ["str_guide_circle_2-3_Lt"] = "Said to be a Light Crystal that appeared after the ancient cataclysm. Can summon dangerous thunderbolts.",
  ["str_guide_circle_2-3_LtT"] = "Light Crystal - Thunderbolt",
  ["str_guide_circle_2-3_Rt"] = "Deals damage equivalent to a percentage of Max HP to all enemies. Very effective.",
  ["str_guide_circle_2-3_RtT"] = "Special Effects",
  ["str_guide_circle_2-3-2_Rt"] = "Special terrain that appears randomly on the battlefield, can be crushed with a ranged Chain Combo.",
  ["str_guide_circle_2-3-2_RtT"] = "Special Trap - Pebbles",
  ["str_guide_circle_2-3-2_Rb"] = "Special rewards might drop from crushing it!",
  ["str_guide_circle_2-3-2_RbT"] = "Pebbles Effect",
  ["str_guide_circle_2-7_Lt"] = "An Eclipsite that uses both arms for double attacks, dealing very high damage.",
  ["str_guide_circle_2-7_LtT"] = "High-ATK Eclipsite - Reaper",
  ["str_guide_circle_2-7_Rt"] = "The attack range of High-ATK Eclipsites is not very large, so just be careful to avoid them.",
  ["str_guide_circle_2-7_RtT"] = "Attack Range",
  ["str_guide_circle_2-7_Rb"] = "Be sure to stay as far away as possible from High-ATK Eclipsites, which deal massive amounts of damage with each attack.",
  ["str_guide_circle_2-7_RbT"] = "Important Tips",
  ["str_guide_circle_2-8_Rt"] = "The Detonation System deals damage to 1 surrounding cluster after 2 rounds. Stay away from it!",
  ["str_guide_circle_2-8_RtT"] = "Detonation System",
  ["str_guide_circle_2-8_Rb"] = "Explosive damage doesn't discriminate between friend and foe, so make your strategy based on the Eclipsites' movement!",
  ["str_guide_circle_2-8_RbT"] = "Important Tips",
  ["str_guide_circle_2-10_Lt"] = "Spellhound is a special monster species that naturally has 3 layers of shield.",
  ["str_guide_circle_2-10_LtT"] = "Shield Monster - Spellhound",
  ["str_guide_circle_2-10_Rt"] = "The shield will only disappear after 3 attacks, so stay close to it more.",
  ["str_guide_circle_2-10_RtT"] = "Coping Strategy",
  ["str_guide_circle_2-10_Rb"] = "Spellhound's shield recovers every few rounds, so attack intensively to defeat it!",
  ["str_guide_circle_2-10_RbT"] = "Important Tips",
  ["str_guide_circle_2-13_Lt_Red"] = "Water Aurorians deal more damage to Fire enemies.",
  ["str_guide_circle_2-13_LtT_Red"] = "Water counters Fire",
  ["str_guide_circle_2-13_Lt_Yellow"] = "Water Aurorians deal less damage to Thunder enemies.",
  ["str_guide_circle_2-13_LtT_Yellow"] = "Water is being countered by Thunder",
  str_guide_circle_None = "Non-elemental types can't be countered by other elements, but they can't counter them either.",
  ["str_guide_circle_2-10-1_Lt"] = "Carries important stolen information and will only drop it when killed.",
  ["str_guide_circle_2-10-1_LtT"] = "Intel Eclipsite",
  ["str_guide_circle_2-10-1_Rt"] = "Pick up the information right away after killing the Datascite, or else it might get stolen!",
  ["str_guide_circle_2-10-1_RtT"] = "Important Tips",
  ["str_guide_circle_ex1-2_Lt"] = "Equipped with paralyzing needles, it can attack the first target in its path at an extremely high speed when triggered.",
  ["str_guide_circle_ex1-2_LtT"] = "Paralysis Ballista",
  ["str_guide_circle_ex1-2_Lb"] = "Penetration is not strong enough. Attacks only the first single target in front, triggered by a trap.",
  ["str_guide_circle_ex1-2_LbT"] = "Attack Range",
  ["str_guide_circle_ex1-3_Lt"] = "Equipped with special Holograms, it can effectively dodge all types of attacks.",
  ["str_guide_circle_ex1-3_LtT"] = "Mirage Force",
  ["str_guide_circle_ex1-3_Rt"] = "Mirage will transmit to a distance after attacking and is difficult to annihilate completely.",
  ["str_guide_circle_ex1-3_RtT"] = "High-speed migration",
  ["str_guide_circle_ex1-3_Rb"] = "Paralysis Ballistae can effectively counter the dodging abilities of the Mirage.",
  ["str_guide_circle_ex1-3_RbT"] = "Important Tips",
  ["str_guide_circle_ex1-4_Lt"] = "Equipped with toxic needles, it attacks the first target in front of it.",
  ["str_guide_circle_ex1-4_LtT"] = "Special M52 Poison",
  ["str_guide_circle_ex1-4_Lb"] = "Penetration is not strong enough. Attacks only the first single target in front, triggered by a trap.",
  ["str_guide_circle_ex1-4_LbT"] = "Attack Range",
  ["str_guide_circle_ex1-6_Rt"] = "Extremely agile, it teleports to another location after attacking and is able to summon a clone.",
  ["str_guide_circle_ex1-6_RtT"] = "Phantom",
  ["str_guide_circle_ex1-6_Rb"] = "Cross-shaped range attack, while Rabid (HP drops to 25%), deals damage across the entire screen.",
  ["str_guide_circle_ex1-6_RbT"] = "Attack Range",
  ["str_guide_circle_ex2-4_Lb"] = "Normal attacks will knock back the target by one tile. It also has very high ACT! Be careful!",
  ["str_guide_circle_ex2-4_LbT"] = "Knockback Eclipsite",
  ["str_guide_circle_ex2-4_Rb"] = "Not only can Eclipsites knock back Aurorian targets, they can also knock back explosives!",
  ["str_guide_circle_ex2-4_RbT"] = "Special Tips",
  ["str_guide_circle_ex4-2_Lb"] = "Moves with rapid speed, making it almost impossible to hit. Also known as a \"Spirit.\"",
  ["str_guide_circle_ex4-2_LbT"] = "Flicker",
  ["str_guide_circle_ex4-2_Rb"] = "Shifts its position before attacking each round.",
  ["str_guide_circle_ex4-2_RbT"] = "Action Pattern",
  ["str_guide_circle_ex4-2_Rt"] = "Use Sniper Aurorians to get into attack range.",
  ["str_guide_circle_ex4-2_RtT"] = "Coping Strategy",
  ["str_guide_circle_ex4-6_Lb"] = "This variant of Flicker is incredibly agile, like an illusion that comes and goes without a trace.",
  ["str_guide_circle_ex4-6_LbT"] = "Formless",
  ["str_guide_circle_ex4-6_Rb"] = "Shifts its position before attacking each round. And it summons a large quantity of Nonentity to the battlefield.",
  ["str_guide_circle_ex4-6_RbT"] = "Action Pattern",
  ["str_guide_circle_ex4-6_Rt"] = "Clear Nonentities from the battlefield and use tile-converting skills to quickly approach Formless and deal damage.",
  ["str_guide_circle_ex4-6_RtT"] = "Coping Strategy",
  ["str_guide_circle_2-3-1_Lt"] = "A modified version of a high-speed piercing trap, with a curved hook head that deals huge damage but with weaker penetration.",
  ["str_guide_circle_2-3-1_LtT"] = "Special SX-3 Rocket",
  ["str_guide_circle_2-3-1_Lb"] = "Attacks the first single target in front of it, triggered once per round.",
  ["str_guide_circle_2-3-1_LbT"] = "Attack Range",
  ["str_guide_circle_2-11_Lb"] = "While enduring corrosion, Eve cannot move nor attack and needs protection.",
  ["str_guide_circle_2-11_LbT"] = "Eve",
  ["str_guide_circle_3-1_Lt"] = "Performs all-round healing, very troublesome.",
  ["str_guide_circle_3-1_LtT"] = "Healer Eclipsite",
  ["str_guide_circle_3-1_Lb"] = "It will not attack us. In fact, it will try to stay away from dangerous targets.",
  ["str_guide_circle_3-1_LbT"] = "Behavioral Characteristics",
  ["str_guide_circle_3-4_Lt"] = "Its forceful attacks deal damage and inflict Stun to the target.",
  ["str_guide_circle_3-4_LtT"] = "Stun Eclipsite",
