  ["str_guide_circle_N3_1-1_RbT"] = "Important Tips",
  ["str_guide_circle_N3_1-1_Rb"] = "Be sure not to stand in a location a Fallen Knight can land, otherwise you'll be stunned.",
  ["str_guide_circle_N3_1-3_LbT"] = "Enraged Rook",
  ["str_guide_circle_N3_1-3_Lb"] = "Attacks according to the movement rules of a rook in chess. Attacks horizontally or vertically.",
  ["str_guide_circle_N3_1-3_RbT"] = "Coping Strategy",
  ["str_guide_circle_N3_1-3_Rb"] = "Try using obstacles to make roundabout attacks on Enraged Rooks.",
  ["str_guide_circle_N3_1-5_LbT"] = "Eclipse Bishop",
  ["str_guide_circle_N3_1-5_Lb"] = "Moves diagonally according to the movement rules of a bishop in chess. Attacks horizontally or vertically.",
  ["str_guide_circle_N3_1-5_RbT"] = "Coping Strategy",
  ["str_guide_circle_N3_1-5_Rb"] = "Use obstacles to your advantage when trying to avoid an Eclipse Bishop's attacks.",
  ["str_guide_circle_N3_1-7_LtT"] = "Deceptive Queen",
  ["str_guide_circle_N3_1-7_Lt"] = "Attacks according to the movement rules of a queen in chess, dealing severe damage to targets in range. If targets are out of range, she waits quietly for the opportunity to strike.",
  ["str_guide_circle_N3_1-7_RtT"] = "Important Tips",
  ["str_guide_circle_N3_1-7_Rt"] = "Be careful not to stay within the Deceptive Queen's early warning range, otherwise you can expect to take a huge amount of damage.",
  ["str_guide_circle_N3_1-9_LtT"] = "Lost Pawn",
  ["str_guide_circle_N3_1-9_Lt"] = "Moves forward each round, delivering a leaping strike. After reaching the lower left edge of the board, is promoted to another piece in the following order: Rook, Knight, Bishop, Queen.",
  ["str_guide_circle_N3_1-9_RtT"] = "Coping Strategy",
  ["str_guide_circle_N3_1-9_Rt"] = "Evade the Lost Pawn - CHAMP's attacks and defeat it before it is promoted.",
  ["str_guide_circle_N3_1-20_LbT"] = "Desolate Monarch",
  ["str_guide_circle_N3_1-20_Lb"] = "Controller of the chess monsters. A master strategist who excels at commanding his troops and forcing the enemy to play right into his hands.",
  ["str_guide_circle_N3_1-20_RbT"] = "Coping Strategy",
  ["str_guide_circle_N3_1-20_Rb"] = "He forces the board to move down one tile each round, accelerating the transformation of his Lost Pawns. Eliminate all of the Lost Pawns on the board as soon as possible, and pay attention to each piece's position each round.",
  ["str_guide_circle_N5_1-3_LtT"] = "Chasm",
  ["str_guide_circle_N5_1-3_Lt"] = "After a certain number of rounds, it releases its inner energy to self-destruct, destroying the terrain.",
  ["str_guide_circle_N5_1-3_RtT"] = "Damaged Tiles",
  ["str_guide_circle_N5_1-3_Rt"] = "Shattered tiles cannot be used by Aurorians.",
  ["str_guide_circle_N5_1-3_RbT"] = "Coping Strategy",
  ["str_guide_circle_N5_1-3_Rb"] = "Defeat the Chasm before it explodes!",
  ["str_guide_circle_N5_1-10_LbT"] = "Hylingerr",
  ["str_guide_circle_N5_1-10_Lb"] = "A giant monster that is as cunning as it is powerful. Deals severe damage to targets in range and has the ability to record target positions.",
  ["str_guide_circle_N5_1-10_RbT"] = "Coping Strategy",
  ["str_guide_circle_N5_1-10_Rb"] = "This monster is relatively bulky. Pay attention to your positioning to avoid most of its damage.",
  ["str_guide_circle_N6_1-10_LtT"] = "Mirren Gautier",
  ["str_guide_circle_N6_1-10_Lt"] = "A fallen noble, his power grows as his hatred for Lumopolis deepened...",
  ["str_guide_circle_N6_1-10_RtT"] = "Hide",
  ["str_guide_circle_N6_1-10_Rt"] = "Can hide when on damaged tiles, becoming immune to damage from normal attacks and skills where a tile is selected.",
  ["str_guide_circle_N6_1-10_LbT"] = "Grudge",
  ["str_guide_circle_N6_1-10_Lb"] = "Can teleport multiple times and break tiles on the battlefield when the enemy is not within attack range.",
  ["str_guide_circle_N6_1-10_RbT"] = "Coping Strategy",
  ["str_guide_circle_N6_1-10_Rb"] = "Eliminate damaged tiles before attacking!",
  ["str_guide_circle_N6_1-1_LtT"] = "Mantleworm",
  ["str_guide_circle_N6_1-1_Lt"] = "An Eclipsite that once dwelled in the depths of the Secret Territory, it excels at launching strikes from underground. It is also said to be able to dig underground passages for other Eclipsites.",
  ["str_guide_circle_N6_1-1_RtT"] = "Note",
  ["str_guide_circle_N6_1-1_Rt"] = "Excels at utilizing damaged terrain, and possesses the ability to deal heavy damage to units around damaged tiles.",
  ["str_guide_circle_N6_1-1_RbT"] = "Coping Strategy",
  ["str_guide_circle_N6_1-1_Rb"] = "Try to minimize the number of damaged tiles on the battlefield and pay attention to your positioning!",
  ["str_guide_circle_N7_1-10_LtT"] = "Maude Solus",
  ["str_guide_circle_N7_1-10_Lt"] = "Undergoes a dangerous temporary transformation without a second thought to gain all-new power.",
  ["str_guide_circle_N7_1-10_RtT"] = "Solus Puppet",
  ["str_guide_circle_N7_1-10_Rt"] = "Can constantly summon Eclipsites to assist in battle.",
  ["str_guide_circle_N7_1-10_LbT"] = "Coping Strategy",
  ["str_guide_circle_N7_1-10_Lb"] = "Prevent Maude from summoning Eclipsites and attack him directly!",
  ["str_guide_circle_N7_1-4_LbT"] = "Stay vigilant!",
  ["str_guide_circle_N7_1-4_Lb"] = "The Eclipsites that transformed after taking \"enhancers\" seem completely different from what we're used to dealing with! Please be careful!",
  ["str_guide_circle_N9_1-3_LbT"] = "???",
  ["str_guide_circle_N9_1-3_Lb"] = "Enigmatic Eclipsite of unknown origin, whose presence does not seem to conform to the reality you know.",
  ["str_guide_circle_N9_1-3_RbT"] = "Monster Traits",
  ["str_guide_circle_N9_1-3_Rb"] = "When not in Aurora Time, gains significant damage reduction.",
  ["str_guide_circle_N9_1-3_LtT"] = "Coping Strategy",
  ["str_guide_circle_N9_1-3_Lt"] = "Attack the monster during Aurora Time!",
  ["str_guide_circle_N9_1-10_LbT"] = "Fearmonger",
  ["str_guide_circle_N9_1-10_Lb"] = "The dust has settled and the identity of a familiar yet alien foe is about to be revealed. It is time to prove your resolve.",
  ["str_guide_circle_N9_1-10_RbT"] = "Monster Traits",
  ["str_guide_circle_N9_1-10_Rb"] = "When not in Aurora Time, gains significant damage reduction. Able to summon minions to aid the battle.",
  ["str_guide_circle_N9_1-10_LtT"] = "Coping Strategy",
  ["str_guide_circle_N9_1-10_Lt"] = "Eliminate the minions and attack Fearmonger as often as possible during Aurora Time!",
  ["str_guide_circle_N11_1-3_LtT"] = "Jammer I",
  ["str_guide_circle_N11_1-3_Lt"] = "A mysterious trap from the Lost City. It seems to be an early Jammer prototype.",
  ["str_guide_circle_N11_1-3_RtT"] = "Trap Characteristics",
  ["str_guide_circle_N11_1-3_Rt"] = "With its ability to disrupt the surrounding area, Aurorians take damage when moving around it.",
  ["str_guide_circle_N11_1-3_LbT"] = "Coping Strategy",
  ["str_guide_circle_N11_1-3_Lb"] = "Careful not to get close to the Jammer when moving!",
  ["str_guide_circle_N11_1-12_LbT"] = "Valencia",
  ["str_guide_circle_N11_1-12_Lb"] = "The inhabitants of the lost city and the offspring of the Illumina explorer—Seamus.",
  ["str_guide_circle_N11_1-12_RbT"] = "Look out!",
  ["str_guide_circle_N11_1-12_Rb"] = "Valencia is able to summon and control powerful traps to aid her in battle. Watch out for her traps out there!",
  ["str_guide_circle_N12_1-1_LbT"] = "Kittypus",
  ["str_guide_circle_N12_1-1_Lb"] = "A special companion of Gretel. It resembles a cat with many legs... It's cute, yet somehow disturbing.",
  ["str_guide_circle_N12_1-1_RbT"] = "Coping Strategy",
  ["str_guide_circle_N12_1-1_Rb"] = "Tentaclaw can transfer the damage sustained to the main body. This feature can be used to counter monsters.",
  ["str_guide_circle_N12_1-2_LbT"] = "Ironstomp",
  ["str_guide_circle_N12_1-2_Lb"] = "A special companion of Gretel. It has a pair of extremely strong legs that can repel any enemy.",
  ["str_guide_circle_N12_1-2_RbT"] = "Coping Strategy",
  ["str_guide_circle_N12_1-2_Rb"] = "Ironstomp is a skilled tile crusher. Bring along tile-converting Aurorians to counter it.",
  ["str_guide_circle_N12_1-3_LbT"] = "Basilisk",
  ["str_guide_circle_N12_1-3_Lb"] = "A special companion of Gretel. Playful and energetic, it particularly enjoys fighting against a group of enemies.",
  ["str_guide_circle_N12_1-3_RbT"] = "Coping Strategy",
  ["str_guide_circle_N12_1-3_Rb"] = "Behind Basilisk's rough skin is a tender heart. Control skills will probably work well against it.",
  ["str_guide_circle_N12_1-4_LbT"] = "Spikeyhog",
  ["str_guide_circle_N12_1-4_Lb"] = "A special companion of Gretel. Generally quiet and placid, but known to go berserk in battle. Approach with caution.",
  ["str_guide_circle_N12_1-4_RbT"] = "Coping Strategy",
  ["str_guide_circle_N12_1-4_Rb"] = "Spikeyhog is covered in spikes. Best for Aurorians to keep a distance.",
  ["str_guide_circle_N13_1-1_LbT"] = "Sword of the Underworld",
  ["str_guide_circle_N13_1-1_Lb"] = "Former chief of the Wisp who's dedicated to fighting Cloud Island invaders.",
  ["str_guide_circle_N13_1-1_RbT"] = "Coping Strategy",
  ["str_guide_circle_N13_1-1_Rb"] = "Sword of the Underworld will make different tactical choices based on her distance from the Aurorians. Keeping your distance and using recovery abilities will help you better deal with her attacks.",
  ["str_guide_circle_N14_1-1_LbT"] = "Nagi - Fury Blade",
  ["str_guide_circle_N14_1-1_Lb"] = "The frenzied Nagi will attack anyone she perceives as an intruder.",
  ["str_guide_circle_N14_1-1_RbT"] = "Coping Strategy",
  ["str_guide_circle_N14_1-1_Rb"] = "Observe Nagi - Fury Blade's attack sequence to avoid Lethal Damage and Counterattack when the opportunity arises.",
  ["str_guide_circle_N13_1-12_LbT"] = "Fujikumo Nobutora",
  ["str_guide_circle_N13_1-12_Lb"] = "A tyrant who came from another Far East island to rule Cloud Island, and he'll do anything to declare sovereignty over it.",
  ["str_guide_circle_N13_1-12_RbT"] = "Watch out!",
  ["str_guide_circle_N13_1-12_Rb"] = "Fujikumo Nobutora can summon a large number of ghosts to assist him in battle.",
  ["str_guide_circle_N13_1-12_LtT"] = "Coping Strategy",
  ["str_guide_circle_N13_1-12_Lt"] = "Clear the ghosts on the battlefield in time.",
  ["str_guide_circle_N14_1-12_LbT"] = "Fujikumo Nobutora - Devour",
  ["str_guide_circle_N14_1-12_Lb"] = "Due to his obsessiveness, he turned into a hideous man and vowed to eliminate all who resisted.",
  ["str_guide_circle_N14_1-12_RbT"] = "Warning!",
  ["str_guide_circle_N14_1-12_Rb"] = "Fujikumo Nobutora - Devour will cast different skills based on the Aurorians' position.",
  ["str_guide_circle_N14_1-12_LtT"] = "Coping Strategy",
  ["str_guide_circle_N14_1-12_Lt"] = "When in battle, position yourself carefully and wait for the best time to counterattack.",
  ["str_guide_circle_N13_1-2_LbT"] = "Ghost",
  ["str_guide_circle_N13_1-2_Lb"] = "A special Far East monster that's said to be \"neither living nor dead\" and is extremely hostile towards the living.",
  ["str_guide_circle_N13_1-2_RbT"] = "Monster Traits",
  ["str_guide_circle_N13_1-2_Rb"] = "Their fighting abilities may not be fearsome, but their numbers are.",
  str_guide_fail_1 = "Nurture Aurorians",
  str_guide_fail_2 = "Raising Aurorian levels and ascending Aurorians are all ways to greatly boost Aurorian abilities",
  str_guide_fail_3 = "Aurorians that can be upgraded: ",
  str_guide_fail_4 = "Obtain Nurturing Materials",
  str_guide_fail_5 = "Obtain Aurorian EXP materials and Breakthrough materials through the following ways",
  str_guide_fail_6 = "Obtained From: Forgotten Snow Resource Stages and Main Stages",
  str_guide_fail_7 = "Tap anywhere to skip",
  str_guide_warn_level_speed = "WARNING Need to level up!",
  str_guide_fail_8 = "Stage failed",
  str_guide_warn_40096 = "Tap here",
  str_guide_fail_9 = "Get familiar with the Skills of each piece",
  str_guide_fail_10 = "Learn each piece's characteristics and bring out their full potential.",
  str_guide_fail_11 = "Adjust combat strategies",
  str_guide_fail_12 = "Each enemy follows a fixed moving pattern. Adjust your combat strategy accordingly.",
  ["str_guide_circle_N17_1-14_LtT"] = "Claudia",
  ["str_guide_circle_N17_1-14_Lt"] = "The AI in the underground base of Eraveil that has been guarding the base for thousands of years and is responsible for clearing out all invading enemies.",
  ["str_guide_circle_N17_1-14_RbT"] = "Monster Traits",
  ["str_guide_circle_N17_1-14_Rb"] = "Perfectly resists normal attacks when standing on the platform or above Asher, immediately jumps to another platform within 2 clusters the moment the one under your feet is smashed.",
  ["str_guide_circle_N17_1-14_LbT"] = "Coping Strategy",
  ["str_guide_circle_N17_1-14_Lb"] = "Use Sniper to get a direct hit on Claudia, also be careful not to destroy the platform.",
  ["str_guide_circle_N17_2-14_LtT"] = "Asher",
  ["str_guide_circle_N17_2-14_Lt"] = "The AI in the underground base of Eraveil who looks big and heavy, it's Claudia's friend.",
  ["str_guide_circle_N17_2-14_RbT"] = "Monster Traits",
  ["str_guide_circle_N17_2-14_Rb"] = "Shows traits of immortality and will get up soon after being knocked down, but the amount of restored HP decreases with each knockdown.",
  ["str_guide_circle_N17_2-14_LbT"] = "Coping Strategy",
  ["str_guide_circle_N17_2-14_Lb"] = "Get around this powerful shield and defeat Claudia as soon as possible.",
  ["str_guide_circle_N18_1-12_LtT"] = "Minos",
  ["str_guide_circle_N18_1-12_Lt"] = "The Andersen's gold medal butler who leaves no stains, trash or vermin unattended.",
  ["str_guide_circle_N18_1-12_RtT"] = "Monster Traits",
  ["str_guide_circle_N18_1-12_Rt"] = "Minos will switch between the Mortal State and Minotaur State based on his stack of Marks. Resets all the tiles he passes to enhanced or weakened tiles depending on his state.",
  ["str_guide_circle_N18_1-12_RbT"] = "Warning!",
  ["str_guide_circle_N18_1-12_Rb"] = "Most of Minos' attacks become stronger as he gains more stacks of his mark. The more stacks of marks he has and the more enhanced tiles on the field, the more dangerous his attacks become.",
  ["str_guide_circle_N18_1-1_LtT"] = "Weakened Tile",
  ["str_guide_circle_N18_1-1_Lt"] = "The special tiles opposite to the enhanced tiles can reduce the damage caused by the player's connections.",
  ["str_guide_circle_N18_1-1_RbT"] = "Characteristics",
  ["str_guide_circle_N18_1-1_Rb"] = "Passing Aurorians will receive a connection damage reduction debuff 2 times that of a normal tile.",
  ["str_guide_circle_N20_1-12_LtT"] = "Core Guardian",
  ["str_guide_circle_N20_1-12_Lt"] = "A gigantic guardian that protects the ship's energy core. It will wake up and fight when the Core is under threat.",
  ["str_guide_circle_N20_1-12_LbT"] = "Venue Characteristics",
  ["str_guide_circle_N20_1-12_Lb"] = "When the Core Guardian is awake, it will rotate the side of the magic cube away from the player at the end of every round, changing the distribution of monsters in the field.",
  ["str_guide_circle_N20_1-12_RbT"] = "Enemy Weaknesses",
  ["str_guide_circle_N20_1-12_Rb"] = "The Freeze Module is the Guardian's weakness. Defeating the Freeze Module will paralyze the Core Guardian for 1 round and make it easier to get hurt.",
  str_guide_warn_5193011 = "P5R Collab characters enter the battle with their Special Skills.",
  str_guide_warn_5193012 = "Tap here to view the Skill Description.",
  str_guide_warn_5193013 = "Launch the Special Skill and take care of these enemies in one go.",
  ["str_guide_circle_N22_1-10_LtT"] = "Casta",
  ["str_guide_circle_N22_1-10_Lt"] = "Seemingly aloof, but actually very responsible. Teamed up with Pollux to form the mercenary duo dubbed \"Raven's Blood\" in order to better defend the kids living in the church.",
  ["str_guide_circle_N22_1-10_RbT"] = "Monster Traits",
  ["str_guide_circle_N22_1-10_Rb"] = "Launches different skill attacks according to the positions of allies; can counteract allied active skills.",
  ["str_guide_circle_N22_1-10_LbT"] = "Coping Strategy",
  ["str_guide_circle_N22_1-10_Lb"] = "Keeps an eye on the relative positions of both sides; controls the frequency of releasing active skills.",
  ["str_guide_circle_sailing_1-1_LtT"] = "Wormgate",
  ["str_guide_circle_sailing_1-1_Lt"] = "Although it is unclear how it works, Eclipsites will continue to appear from it. The battle will probably become very difficult if it is not dealt with as soon as possible.",
  ["str_guide_circle_sailing_1-1_RbT"] = "Characteristics",
  ["str_guide_circle_sailing_1-1_Rb"] = "If the Wormgate is opened, Eclipsites will be summoned at the beginning of the next round.",
  ["str_guide_circle_sailing_1-1_RtT"] = "Warning!",
  ["str_guide_circle_sailing_1-1_Rt"] = "If an Eclipsite is standing above the Wormgate at the beginning of the round, the Wormgate will not summon new Eclipsites in this round.",
  ["str_guide_circle_sailing_2-1_LtT"] = "Halo Stone",
  ["str_guide_circle_sailing_2-1_Lt"] = "Rocks with unknown Lumina, commonly present in ruins, rumored to change the Lumina around them.",
  ["str_guide_circle_sailing_2-1_RbT"] = "Characteristics",
  ["str_guide_circle_sailing_2-1_Rb"] = "At the beginning of each player round, the Halo Stone converts all tiles of a different element within a certain range into the same element as itself.",
  ["str_guide_circle_sailing_2-1_RtT"] = "Strategy",
  ["str_guide_circle_sailing_2-1_Rt"] = "The element of the Halo Stone will always be the same as the element of the tile it is on. Our allies can use this to seize the advantage in battle.",
  ["str_guide_circle_sailing_2-2_RbT"] = "Warning!",
  ["str_guide_circle_sailing_2-2_Rb"] = "If the tile under the Halo Stone becomes a chromatic tile, the Halo Stone will be destroyed.",
  ["str_guide_circle_sailing_2-3_LtT"] = "Skill Banning Stele",
  ["str_guide_circle_sailing_2-3_Lt"] = "A short mysterious stele found in certain ruins. The runes on it impose certain restrictions on attackers.",
  ["str_guide_circle_sailing_2-3_RbT"] = "Characteristics",
  ["str_guide_circle_sailing_2-3_Rb"] = "Silences all Aurorians within a certain range, making them unable to use active skills.",
  ["str_guide_circle_sailing_2-4_LtT"] = "Strategy",
  ["str_guide_circle_sailing_2-4_Lt"] = "Use a chain combo skill or active skill that deals area damage to deal damage to Skill Banning Steles. They will break after taking a certain amount of damage.",
  ["str_guide_circle_N22_2-1_LtT"] = "Monster Traits",
  ["str_guide_circle_N22_2-1_Lt"] = "It can use turrets to deal continuous damage to the enemy and drive away any enemies that come too close to it. The guard will strengthen itself when it perceives a huge threat.",
  ["str_guide_circle_N22_2-1_RtT"] = "Coping Strategy",
  ["str_guide_circle_N22_2-1_Rt"] = "The Self-Propelled Cannon can deal damage to the same enemy multiple times in the same round, but it isn't necessary for the player to avoid every hit as it doesn't deal much damage with each hit.",
  ["str_guide_circle_N22_2-1_RbT"] = "Self-Propelled Cannon",
  ["str_guide_circle_N22_2-1_Rb"] = "Powerful guards capable of patrolling on their own. Both the main and shoulder cannons are incredibly powerful. Just one such guard can cause great damage.",
  ["str_guide_circle_N23_1-14_LtT"] = "Astor",
  ["str_guide_circle_N23_1-14_Lt"] = "A roaming, female spirit with neither a master nor a will of its own; all that remains is a powerful enmity towards the living. Through sinister rituals, this spirit can be combined with Darkflow to create a powerful supernatural entity.",
  ["str_guide_circle_N23_1-14_RtT"] = "Monster Traits",
  ["str_guide_circle_N23_1-14_Rt"] = "Rampages through a designated area and absorbs the energy of Deathly Candles to strengthen itself.",
  ["str_guide_circle_N23_1-14_RbT"] = "Coping Strategy",
  ["str_guide_circle_N23_1-14_Rb"] = "Extinguish Deathly Candles to maintain distance from Astor.",
  ["str_guide_circle_13-14_LtT"] = "Diavola",
  ["str_guide_circle_13-14_Lt"] = "The exterior of the flower body is guarded heavily by tough leaves, but Sniper skills can deal lethal damage to the flower and expose its weakness.",
  ["str_guide_circle_13-14_RtT"] = "Monster Traits",
  ["str_guide_circle_13-14_Rt"] = "When awakened, Diavola counters every normal attack dealt by Aurorians and inflicts 1 stack of Toxin on them.",
  ["str_guide_circle_13-14_RbT"] = "Coping Strategy",
  ["str_guide_circle_13-14_Rb"] = "Prioritize attacking the flowers of Diavola first to paralyze it in order to safely deal damage to it. Remember to take care of the Dawn Sprites it summons.",
  ["str_guide_circle_13-7-1_Lt"] = "An Eclipsite born in the extreme conditions of the end of days. It has a distorted figure and has long lost the ability to think intelligently. All it has left is the desire to keep moving forward and devouring everything in its way.",
  ["str_guide_circle_13-7-1_LtT"] = "Jormungand",
  ["str_guide_circle_13-7-1_Rt"] = "Jormungand's head is the core of its attacks. It deals a lot of damage to enemies near its head. Jormungand dies when its head has 0 HP remaining.",
  ["str_guide_circle_13-7-1_RtT"] = "Characteristics of Jormungand's Head",
  ["str_guide_circle_13-7-1_Rb"] = "Players must remember to deal damage to Jormungand's head from a distance. Jormungand will die immediately if its head is blocked by obstacles on all sides.",
  ["str_guide_circle_13-7-1_RbT"] = "Coping Strategy",
  ["str_guide_circle_13-7-2_Lt"] = "Jormungand's body replicates itself over time and grows longer every round. Its body is immune to all damage.",
  ["str_guide_circle_13-7-2_LtT"] = "Characteristics of Jormungand's Body",
  ["str_guide_circle_13-7-3_Lt"] = "Jormungand's tail is its weak point. All damage dealt to the tail will be transferred to the head, and you'll deal more damage.",
  ["str_guide_circle_13-7-3_LtT"] = "Characteristics of Jormungand's Tail",
  ["str_guide_circle_14-9-1_LtT"] = "Lantern Spirit",
  ["str_guide_circle_14-9-1_Lt"] = "An Eclipsite that was modified by Asmodeus. Its desires are controlled by Asmodeus, so it obeys her every command.",
  ["str_guide_circle_14-9-1_RtT"] = "Characteristics of Monsters I",
  ["str_guide_circle_14-9-1_Rt"] = "If a Lantern Spirit can Teleport through Aurorians when attacking, it creates a chain that causes both damage received and HP recovered to be shared between the linked parties.",
  ["str_guide_circle_14-9-1_RbT"] = "Teleport",
  ["str_guide_circle_14-9-1_Rb"] = "The Lantern Spirit can Teleport if it can pass through the tile the Aurorian is on and move to the tile on the other side.",
  ["str_guide_circle_14-9-2_LtT"] = "Chains",
  ["str_guide_circle_14-9-2_Lt"] = "When either party connected by the chain takes damage or recovers HP, the other party will take the same amount of damage or recover the same amount of HP.",
  ["str_guide_circle_14-9-2_RtT"] = "Coping Strategy",
  ["str_guide_circle_14-9-2_Rt"] = "Keep a certain distance from a Lantern Spirit to break the chain.",
  ["str_guide_circle_14-9-2_RbT"] = "Defeat or draw them over!",
  ["str_guide_circle_14-9-2_Rb"] = "Defeating or drawing the Lantern Spirit towards you is also a way to break free from the chain connecting you.",
  ["str_guide_circle_14-14-1_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-1_Lt"] = "The powerful Wraith has the terrifying ability to see through all the desires of its opponents and enjoys manipulating them.",
  ["str_guide_circle_14-14-1_RtT"] = "Characteristics of Eclipsites",
  ["str_guide_circle_14-14-1_Rt"] = "Asmodeus divides into two when entering the field. One clone is immune to skills, and the other is immune to normal attacks. They are connected by the Chain of Desire.",
  ["str_guide_circle_14-14-1_RbT"] = "Chain of Desire",
  ["str_guide_circle_14-14-1_Rb"] = "When either Asmodeus connected by the Chain of Desire takes damage or recovers HP, the other Asmodeus will undergo the same effect. After Asmodeus takes action, Dark Regions will be generated under the Chain of Desire.",
  ["str_guide_circle_14-14-2_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-2_Lt"] = "This Asmodeus is immune to normal attack damage and has powerful ranged attacks.",
  ["str_guide_circle_14-14-3_RtT"] = "Asmodeus",
  ["str_guide_circle_14-14-3_Rt"] = "This Asmodeus is immune to skill damage and links herself to Aurorians she hits with her Chain of Nightmares.",
  ["str_guide_circle_14-14-3_RbT"] = "Chain of Nightmares",
  ["str_guide_circle_14-14-3_Rb"] = "Aurorians connected by the Chain of Nightmares will take damage for every tile they traverse. Leaving the effective range of the Chain of Nightmares will break it.",
  ["str_guide_circle_14-7_LtT"] = "Cerritus",
  ["str_guide_circle_14-7_Lt"] = "The new Eclipsite encountered during the exploration seems to be a variant of a powerful Eclipsite, except it is more deranged and far more destructive.",
  ["str_guide_circle_14-7_RtT"] = "Monster Traits",
  ["str_guide_circle_14-7_Rt"] = "Cerritus attacks Aurorians by ramming into them and has the powerful ability to summon Pebbles and change the terrain. Cerritus grows stronger as the battle progresses. Attacks that don't kill Cerritus only make it stronger! Every few rounds, Cerritus roars angrily and enters a mad state.",
  ["str_guide_circle_14-7_RbT"] = "Coping Strategy",
  ["str_guide_circle_14-7_Rb"] = "Pay attention to your relative position from enemies. Use skills at the right time to end battles quickly.",
  str_guide_circle_N24_petTry_LtT = "Healing Orb",
  str_guide_circle_N24_petTry_Lt = "Axelia's summoned object. She heals herself when she absorbs this with her Active Skill or when the team passes through it. Transforms after existing for 2 rounds, provides additional healing effects.",
  str_guide_circle_N24_petTry_Lt_1 = "Axelia's summoned object. She heals herself when she absorbs this with her Active Skill or when the team passes through it.",
  ["str_guide_circle_N25_1-4_LtT"] = "Venomex",
  ["str_guide_circle_N25_1-4_Lt"] = "Said to be a distant relative of a species of Eclipsite able to self-detonate, except this variety can launch venomous slime balls, dealing significant damage to living organisms.",
  ["str_guide_circle_N25_1-4_LbT"] = "Monster Traits",
  ["str_guide_circle_N25_1-4_Lb"] = "Sprays poison in a straight line or in an Aurorian's location, inflicting Poison on all enemies and allies within the venom's range.",
  ["str_guide_circle_N25_1-4_RtT"] = "Strategy",
  ["str_guide_circle_N25_1-4_Rt"] = "Maybe you can use its poison to make other enemies suffer.",
  ["str_guide_circle_N25_1-16_RtT"] = "Dreamwalker",
  ["str_guide_circle_N25_1-16_Rt"] = "It's said to be the Phantom's \"brother\" in Eternal Night. It's able to use different tactics according to the time of the day and is extremely difficult to deal with.",
  ["str_guide_circle_N25_1-16_LtT"] = "Monster Traits",
  ["str_guide_circle_N25_1-16_Lt"] = "Has the ability to attack Aurorians from a distance and can launch full-screen attacks. Can summon phantoms that surround Aurorians but cannot attack.",
  ["str_guide_circle_N25_1-16_LbT"] = "Strategy",
  ["str_guide_circle_N25_1-16_Lb"] = "Rely on nimble movement to avoid getting surrounded by Phantasms.",
  ["str_guide_circle_N25_2-4_LtT"] = "Cozen",
  ["str_guide_circle_N25_2-4_Lt"] = "Possesses a remarkable ability to blend into its surroundings. Sometimes, it even looks like an ordinary trap. However, once it reveals itself, it erupts in a murderous rampage.",
  ["str_guide_circle_N25_2-4_LbT"] = "Monster Traits",
  ["str_guide_circle_N25_2-4_Lb"] = "Usually hides in Crud. When the countdown is over, it appears and attacks Aurorians.",
  ["str_guide_circle_N25_2-4_RtT"] = "Coping Strategy",
  ["str_guide_circle_N25_2-4_Rt"] = "Resetting tiles where Crud is located will remove the Crud and make a Cozen appear.",
  ["str_guide_circle_N26_1-12_RtT"] = "Yoh",
  ["str_guide_circle_N26_1-12_Rt"] = "Once the leader of the serpentfish, he was enslaved by Aurorians to serve as a navigation tool. Years of mounting hatred has turned him into a powerful fiendling.",
  ["str_guide_circle_N26_1-12_LtT"] = "Monster Traits",
  ["str_guide_circle_N26_1-12_Lt"] = "Possesses powerful magic abilities and can control projectiles to deal damage to enemies.",
  ["str_guide_circle_N26_1-12_LbT"] = "Coping Strategy",
  ["str_guide_circle_N26_1-12_Lb"] = "Clear \"Word\" and the replicas on the field as soon as possible to avoid heavy damage.",
  ["str_guide_circle_N27_1-1_RtT"] = "Aphonic Assistant",
  ["str_guide_circle_N27_1-1_Rt"] = "Possible a certain type of Eclipsite's \"mentor,\" seeing as how they both heal other Eclipsites. The difference is that this Eclipsite is more likely to stay close to its bulkier allies in order to make the most of its skill's special effect.",
  ["str_guide_circle_N27_1-1_LtT"] = "Monster Traits",
  ["str_guide_circle_N27_1-1_Lt"] = "Can restore the HP of other Eclipsites. The more tiles occupied by other Eclipsites within Aphonic Assistant's skill range, the stronger the effect of its healing.",
  ["str_guide_circle_N27_1-1_LbT"] = "Coping Strategy",
  ["str_guide_circle_N27_1-1_Lb"] = "Prioritize dealing with Aphonic Assistant, and prevent Aphonic Assistant from healing the other Eclipsites!",
  ["str_guide_circle_N27_1-12_LtT"] = "Pink Sandworm",
  ["str_guide_circle_N27_1-12_Lt"] = "A rare sandworm native to the Rediesel Desert. It is covered in pink scales due to a unique mutation, making it more powerful and fiercer than other sandworms.",
  ["str_guide_circle_N27_1-12_RtT"] = "Monster Traits",
  ["str_guide_circle_N27_1-12_Rt"] = "Drills into the ground to find the location of its target, then bursts out into the open. Spits black sand to attack targets in front of it.",
  ["str_guide_circle_N27_1-12_RbT"] = "Coping Strategy",
  ["str_guide_circle_N27_1-12_Rb"] = "Avoiding the Pink Sandworm's attacks can be tricky! Pay attention to your own status at all times and end the battle as soon as you can!",
  ["str_guide_circle_N27_2-4-1_RbT"] = "Paper Crane",
  ["str_guide_circle_N27_2-4-1_Rb"] = "Paper Cranes can be placed on Abyssal tiles and converted tiles beneath them to chromatic tiles. Paper Cranes will disappear after the team passes through them.",
  ["str_guide_circle_N27_2-4-2_RbT"] = "Aurorian Assistance",
  ["str_guide_circle_N27_2-4-2_Rb"] = "Pasolo can place Paper Cranes on tiles to help her team overcome difficult situations. Remember to use Pasolo's skill assistance every round!",
  str_guide_circle_N27_2_1_RtT = "Lumo Backup",
  str_guide_circle_N27_2_1_Rt = "Backup teams from Lumopolis have joined the battle. Allied Pikers will act after the Eclipsites. The Constructor will summon a Piker when the player casts the Active Skill 3 times in succession.",
  str_guide_circle_N27_2_1_RbT = "Warning!",
  str_guide_circle_N27_2_1_Rb = "Protect the allied Constructor first! Once the Constructor gets defeated, allied Lumo Pikers will have to retreat. DEF of all Aurorians on the board will also be greatly weakened.",
  str_guide_circle_N27_2_2_RbT = "Attack Target",
  str_guide_circle_N27_2_2_Rb = "Eclipsites will attack our Lumo Backup first. Once all Lumo Backup teams on the board is defeated, Eclipsites will change their target and attack the player.",
  str_guide_circle_N27_2_2_LbT = "Faction Fight",
  str_guide_circle_N27_2_2_Lb = "The enemy's Evil Eye will continue to summon Eclipsites to the battlefield. Players need to protect the allied Constructor and defeat the enemy's Brood.",
  str_guide_circle_N28_3_4_RtT = "Wormhole",
  ["str_guide_circle_N28_3-4_Rt"] = "Eclipsites can escape to other locations through wormholes.",
  ["str_guide_circle_N28_3-4_RbT"] = "Coping Strategy",
  ["str_guide_circle_N28_3-4_Rb"] = "Prevent Eclipsites from escaping by defeating them or using abilities that force them to move.",
  str_guide_circle_N28_1_12_LtT = "The Four Knights",
  str_guide_circle_N28_1_12_Lt = "Although they look like ordinary jury members, the plaster headgears on their heads make them look very suspicious. It turns out to be Eclipsites hiding under them! The confusing thing is that they seem to be following someone's instructions...",
  str_guide_circle_N28_1_12_LbT = "Monster Traits",
  str_guide_circle_N28_1_12_Lb = "Whenever 1 of the Four Knights is attacked or recovers HP, the other knights will take the same amount of damage or recover the same amount of HP.",
  str_guide_circle_N28_1_12_RbT = "Coping Strategy",
  str_guide_circle_N28_1_12_Rb = "Carefully observe the position of the Four Knights and act with caution!",
  str_guide_circle_N29_zhanqi_1_LtT = "Wormhole",
  str_guide_circle_N29_zhanqi_1_Lt = "Helps Eclipsites move faster across the battlefield.",
  str_guide_circle_N29_zhanqi_1_LbT = "Coping Strategy",
  str_guide_circle_N29_zhanqi_1_Lb = "Avoiding conflict with Aurorians and passing through the teleport device as soon as possible seems to be a more sensible option.",
  str_guide_circle_N29_1_8_LbT = "Demon Hati",
  str_guide_circle_N29_1_8_Lb = "Memories of the past flooded her heart, creating the fearsome Demon Hound as hatred seized control.",
  str_guide_circle_N29_1_8_RbT = "Monster Traits",
  str_guide_circle_N29_1_8_Rb = "Demon Hati consumes a portion of her HP to attack and recovers a portion of her lost HP if any Aurorians are hit. Demon Hati deals more damage as her HP decreases!",
  str_guide_circle_N29_1_14_LbT = "Demon Hati",
  str_guide_circle_N29_1_14_Lb = "Memories of the past flooded her heart, creating the fearsome Demon Hound as hatred seized control.",
  str_guide_circle_N29_1_14_RbT = "Monster Traits",
  str_guide_circle_N29_1_14_Rb = "Demon Hati consumes a portion of her HP to attack and recovers a portion of her lost HP if any Aurorians are hit. Demon Hati deals more damage as her HP decreases!",
  str_guide_circle_N29_1_14_LbT_2 = "Watch out!",
  str_guide_circle_N29_1_14_Lb_2 = "When Demon Hati is on the verge of death, she can consume regenerative energy to restore herself to full HP. She will also gain a powerful skill and enhance her skill effects!",
  str_guide_circle_N29_ex3_1_LbT = "Demon Hati",
  str_guide_circle_N29_ex3_1_Lb = "Memories of the past flooded her heart, creating the fearsome Demon Hound as hatred seized control.",
  str_guide_circle_N29_ex3_1_RbT = "Monster Traits",
  str_guide_circle_N29_ex3_1_Rb = "Demon Hati consumes a portion of her HP to attack and recovers a portion of her lost HP if any Aurorians are hit. Demon Hati deals more damage as her HP decreases!",
  str_guide_circle_N29_ex3_1_LbT_2 = "Watch out!",
  str_guide_circle_N29_ex3_1_Lb_2 = "When Demon Hati is on the verge of death, she can consume regenerative energy to restore herself to full HP. She will also gain a powerful skill and enhance her skill effects!",
  str_guide_circle_N29_ex3_1_RbT_2 = "Warning!",
  str_guide_circle_N29_ex3_1_Rb_2 = "Demon Hati counters Active Skills if Aurorians cast them against her.",
  str_guide_warn_11900702 = "This is the refinement level of the current equipment. Each equipment can be refined 3 times.",
  str_guide_warn_11900703 = "Equipment refinement effects are shown here. In addition to improving basic attributes, refinement can also upgrade Aurorian skills.",
  str_guide_warn_11900704 = "In addition to meeting the basic unlocking requirements for refinement, Aurorians also need to consume the corresponding materials.",
  str_guide_warn_11900802 = "This is the refinement level of the current equipment. Each equipment can be refined 3 times.",
  str_guide_warn_11900803 = "Equipment refinement effects are shown here. In addition to improving basic attributes, refinement can also upgrade Aurorian skills.",
  str_guide_warn_11900804 = "In addition to meeting the basic unlocking requirements for refinement, Aurorians also need to consume the corresponding materials.",
  str_guide_warn_11900805 = "Paradigm can be obtained through weekly Activity awards, among other methods. Tap the icon to view the detailed list of Paradigm sources.",
  ["str_guide_circle_N30_15-2_RtT"] = "Illumina Soldiers",
  ["str_guide_circle_N30_15-2_Rt"] = "Common combat soldiers in the Illumina Army, known for their skill with rifles and combat knives, as well as their tenacity, work ethic, proactiveness in battle, and fearless fighting spirit.",
  ["str_guide_circle_N30_15-2_LbT"] = "Monster Traits",
  ["str_guide_circle_N30_15-2_Lb"] = "Uses more ranged attacks. When the battle is fierce, rushes up to enemies and engages them in melee combat to finish them off as soon as possible.",
  ["str_guide_circle_N30_15-2_RbT"] = "Watch out!",
  ["str_guide_circle_N30_15-2_Rb"] = "When HP is lower than 50%, all weapon attacks will become melee attacks with a combat knife. At the same time, all accumulated Bruise will turn into restored HP and increase ATK and DEF.",
  ["str_guide_circle_N30_15-9_Lt"] = "A combat robot developed by Illumina. It has performed extremely well in internal tests but hasn't been tested in actual combat yet.",
  ["str_guide_circle_N30_15-9_LtT"] = "Driller",
  ["str_guide_circle_N30_15-9_Lb"] = "Driller has 2 states. It moves around the field in its normal state and digs a certain number of Energy Fields and Support Fields every round. When there are a certain number of Energy Fields on the field, it absorbs and assembles a Driller Platform.",
  ["str_guide_circle_N30_15-9_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_N30_15-9_Rb"] = "When there are fewer Support Fields on the field, Driller digs more Support Fields.",
  ["str_guide_circle_N30_15-9_RbT"] = "Note",
  ["str_guide_circle_N30_15-9-2_Lt"] = "Energy Fields are fully energized tiles that can be used to assemble the Driller Platform. It stops the passage of units on the ground when it is present.",
  ["str_guide_circle_N30_15-9-2_LtT"] = "Energy Field",
  ["str_guide_circle_N30_15-9-2_Rb"] = "If there are 6 Energy Fields on the battlefield when Driller takes action, Driller triggers a special skill, constructing a Driller Platform.",
  ["str_guide_circle_N30_15-9-2_RbT"] = "Parts required for assembly.",
  ["str_guide_circle_N30_16-14_Lt"] = "As one of the most powerful Wraiths, he attacks with all his strength when his status is threatened.",
  ["str_guide_circle_N30_16-14_LtT"] = "Figerald",
  ["str_guide_circle_N30_16-14_Lb"] = "Tiles collapse after Aurorians move across them. When there aren't enough tiles on the battlefield, Figerald releases his power to reshape the space and deals damage.",
  ["str_guide_circle_N30_16-14_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_N30_16-14_Rt"] = "Plan your route well to minimize the number of times you take damage when Figerald reshapes space.",
  ["str_guide_circle_N30_16-14_RtT"] = "Coping Strategy",
  str_guide_circle_N30_tower10_LtT = "Mechanical Huntsman",
  str_guide_circle_N30_tower10_LbT = "Enemy Characteristics",
  str_guide_circle_N30_tower10_RbT = "Warning!",
  str_guide_circle_N30_tower10_Lt = "An ancient guardian created for the sole purpose of protecting the secrets of this land. Its attacks are difficult to escape from, and it also has incredible self-recovery to keep it functioning through the ages. No one will want to face it alone.",
  str_guide_circle_N30_tower10_Lb = "Creates a guarded zone within 2 surrounding clusters of itself every round. Aurorians within the guarded zone will take additional damage whenever they attack or move. If Mechanical Huntsman is invincible when it takes action, it will consume its regenerative energy to restore itself to full HP.",
  str_guide_circle_N30_tower10_Rb = "When Mechanical Huntsman enters the invincible state, it unleashes an extremely dangerous attack that reduces all enemies in the guarded zone to 1 HP in the next round.",
  str_guide_circle_N30_tower10_3_LtT = "Bennuguardian",
  str_guide_circle_N30_tower10_3_Lt = "An ancient guardian residing in Secret Territory depths, awakened due to frequent disturbances from intruders. Even Eclipsites are afraid of its powerful abilities. Wanders around the battlefield aimlessly.",
  str_guide_circle_N30_tower10_3_LbT = "Enemy Characteristics",
  str_guide_circle_N30_tower10_3_Lb = "Possesses great power. Accumulates Fury when attacked. When Fury reaches a certain level, enters an Enraged state, reducing damage taken and casting additional powerful skills. If Bennuguardian is invincible when it takes action, it will consume its regenerative energy to restore itself to full HP.",
  str_guide_circle_N30_tower10_3_RbT = "Warning!",
  str_guide_circle_N30_tower10_3_Rb = "Monitor Bennuguardian's Fury at all times and act cautiously!",
  ["str_guide_circle_15-14_LtT"] = "Test State Helios",
  ["str_guide_circle_15-14_Lt"] = "After living alone for more than a decade in the Dark Zone, this Illumina soldier has forgotten everything except fighting. The frightening thing is that he has become stronger in battle after being modified by someone...",
  ["str_guide_circle_15-14_RtT"] = "Enemy Characteristics",
  ["str_guide_circle_15-14_Rt"] = "An entity that has strong combat abilities and accumulates Bruises when taking damage. When his attacks miss his target, a Terror Mark is released on the field. Helios' skills become more powerful with every Terror Mark on the field.",
  ["str_guide_circle_15-14_RbT"] = "Coping Strategy",
  ["str_guide_circle_15-14_Rb"] = "Take note of where the marks are to avoid Helios's attacks!",
  str_guide_circle_621_RtT = "Cross-Shaped Prism Tile",
  str_guide_circle_621_Rt = "When it is connected with other tiles, the 4 tiles around it in a cross shape are converted to the same color.",
  ["str_guide_circle_N30_16-9_Lt"] = "This special Eclipsite resembles spiders and has learned the behavior of spider groups during its evolutionary path. It hides in the darkness where sunlight cannot reach.",
  ["str_guide_circle_N30_16-9_LtT"] = "Spider Queen",
  ["str_guide_circle_N30_16-9_Lb"] = "Possessing strong reproductive abilities, it weaves spider webs into a hunting environment.",
  ["str_guide_circle_N30_16-9_LbT"] = "Monster Traits",
  ["str_guide_circle_N30_16-9_Rt"] = "Focus your attention on clearing the webs, and clear the Spider Queen's summoned Spider Eggs and Spider Hatchlings as quickly as you can.",
  ["str_guide_circle_N30_16-9_RtT"] = "Coping Strategy",
  ["str_guide_circle_N30_16-3_Lt"] = "An outstanding member of Illumina and understated melee combat expert with the ability to detect and react to the enemy's movements during intense battles, allowing for effective counterattacks.",
  ["str_guide_circle_N30_16-3_LtT"] = "Elite Illumina Soldier",
  ["str_guide_circle_N30_16-3_Lb"] = "Each time the enemy uses an Active Skill, instantly advances 1 tile toward the enemy and attacks.",
  ["str_guide_circle_N30_16-3_LbT"] = "Counter Ability",
  ["str_guide_circle_N30_16-3_Rt"] = "Accumulates Bruises when taking damage. If the player doesn't deal damage to this unit during this round, immediately heals all Bruises to restore HP.",
  ["str_guide_circle_N30_16-3_RtT"] = "Tenacious Enhancement",
  str_guide_warn_12000101 = "The Illumination's Descent event is now underway! During the event period, the Illumina Supply Center will be open to all Navigators!",
  str_guide_warn_12000102 = "Supplies Passes obtained by spending Prism can be exchanged for various rewards in the Illumina Supply Center.",
  str_guide_warn_12000103 = "Enter Gronru's new Team Battle military exercise simulator to engage in comprehensive training with your Aurorians!",
  str_guide_warn_12000104 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_12000105 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_12000106 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_12100101 = "Journey to the Past has now begun! We'll revisit the old times with Mia on Family Day and unravel the truth behind what happened!",
  str_guide_warn_12100102 = "In Bottomless Chasm, we'll face a series of difficult challenges.",
  str_guide_warn_12100103 = "Crystal Droplets obtained by completing event stages and spending Prism can be used to redeem various rewards from Divination Room.",
  str_guide_warn_12100104 = "Remember to log into the game every day to get On Memories of Old rewards.",
  str_guide_warn_12100105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_12100106 = "If you have any questions about the event, you can view the detailed description here.",
  ["str_guide_circle_N31_1-14_Lt"] = "Mime Kartima brandishes his shield, reducing damage from frontal attacks. Loses effect when stunned, frightened, paralyzed, or inflicted with other control effects.",
  ["str_guide_circle_N31_1-14_LtT"] = "Kartima: Shieldguard",
  ["str_guide_circle_N31_1-14_Lb"] = "Mime Kartima immunes to control effects for 2 rounds after joining the battle.",
  ["str_guide_circle_N31_1-14_LbT"] = "Kartima: Unyielding",
  ["str_guide_circle_N31_1-14_Rt"] = "Mime Kartima uses the chain hammer to attack an area in front to his right or uses the shield to knock back the target in front to the left",
  ["str_guide_circle_N31_1-14_RtT"] = "Battle Technique",
  ["str_guide_circle_N31_1-16_Lt"] = "She has immense control over her surroundings and is partially resistant to normal attacks and skills due to the effect of the Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LtT"] = "Joshua: Tainted Soul",
  ["str_guide_circle_N31_1-16_Lb"] = "Choose different action strategies, such as whether to use normal attacks or skills against Joshua: Tainted Soul in the current round based on the effect of the Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LbT"] = "Battle Technique",
  str_guide_popstar_fail_tip = "Elimination Strategy",
  str_guide_popstar_fail_desc = "Use Aurorian skills to remove as many tiles as possible at each step. When removing tiles, thinking carefully about the condition the tiles will be in during the next step will make things infinitely easier for you.",
  str_guide_circle_N31_star1_Rt = "Can be removed along with tiles. If not removed, turns into a broken tile after the countdown ends.",
  str_guide_circle_N31_star1_RtT = "Rune Tile",
  str_guide_circle_N31_star2_Rt = "When removing enhanced tiles, this tile is treated as an additionally removed tile.",
  str_guide_circle_N31_star2_RtT = "Enhanced Tile",
  str_guide_circle_N31_star3_Rt = "Locked tiles cannot have their color converted. After removing locked tiles, they are converted into normal tiles.",
  str_guide_circle_N31_star3_RtT = "Locked Tile",
  str_guide_warn_6012102 = "Tap here to view rank details.",
  str_guide_warn_6012104 = "Tap here to view the Ranking.",
  str_guide_warn_6012106 = "Tap here to continue viewing.",
  str_guide_warn_6012107 = "You can obtain Forgotten Utterances and Forgotten Whispers by completing Hunting Bounties.",
  str_guide_warn_6012108 = "Navigators can exchange Forgotten Utterances and Forgotten Whispers at the Exiled Harborage for Solamber, Aurorians and Star Flares.",
  str_guide_warn_6012202 = "We can set up multiple teams to challenge the bosses. The total damage of all our teams will be recorded as the final result.",
  str_guide_warn_6012203 = "No rankings or emblems will be available if you haven't started your challenge.",
  str_guide_warn_6012204 = "Tap here to view rank details.",
  str_guide_warn_6012206 = "Tap here to view your Current Ranking.",
  str_guide_warn_6012208 = "Tap here to continue viewing.",
  str_guide_warn_6012209 = "You can obtain Forgotten Utterances and Forgotten Whispers by completing Hunting Bounties.",
  str_guide_warn_6012210 = "Navigators can exchange Forgotten Utterances and Forgotten Whispers at the Exiled Harborage for Solamber, Aurorians and Star Flares.",
  str_guide_warn_12200201 = "Huh? Where am I? Is that a... another Crystal of Eternal Memory?",
  str_guide_warn_12200202 = "Did we fail to get out in the end...? It's okay! Recite the time travel spell out aloud and tap here!",
  str_guide_warn_12200301 = "Shush... Someone seems to be talking nearby. Ahem, I'm not eavesdropping! This is called... information gathering!",
  str_guide_warn_12200401 = "See? I knew I was right. We got our hands on some incredible information! What? You can't remember everything? Then put the information we gathered here!",
  str_guide_warn_12200402 = "See, all the information is here, now you don't need to worry about forgetting things! Pay attention to everything around you and fill all this space up.",
  str_guide_warn_12200101 = "The Edge of Collapse has started! In The Divergence, we'll investigate the mystery of the Crystal of Eternal Memory!",
  str_guide_warn_12200102 = "We'll face a series of difficult challenges in the world of Shattered Illusion.",
  str_guide_warn_12200103 = "Crystal Teardrops obtained by completing event stages and spending Prism can be exchanged for various rewards at the Hall of Remembrance.",
  str_guide_warn_12200104 = "Remember to log into the game every day to get Wistful Musing rewards.",
  str_guide_warn_12200105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_12200106 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_circle_N33_15_Lt = "An extremely rare butterfly, rumored to only appear near Denuo Valley. It's reclusive by nature, with highly acute senses. The combat power of adult Denuo Goddesses should not be underestimated.",
  str_guide_circle_N33_15_LtT = "Denuo Goddess",
  str_guide_circle_N33_15_Lb = "They catalyze plant growth through pollination, protecting themselves while dealing massive damage to foes.",
  str_guide_circle_N33_15_LbT = "Enemy Characteristics",
  str_guide_circle_N33_15_Rt = "Choose your path wisely to prevent the Denuo Goddess from pollinating the Sadesian Enchantweed and making it more aggressive.",
  str_guide_circle_N33_15_RtT = "Coping Strategy",
  str_guide_circle_chapter18_14_Rb = "Engage in intensive attacks to paralyze Corrupted Engine VII, delaying its assault on the gate of Illumina Stronghold.",
  str_guide_circle_chapter18_14_RbT = "Coping Strategy",
  str_guide_circle_chapter18_14_Rt = "Originally a colossal combat mecha crafted by Illumina, it turned into one of the most formidable threats after its pilot lost their mind due to contamination by the mud.",
  str_guide_circle_chapter18_14_RtT = "Corrupted Engine VII",
  str_guide_warn_80010102 = "Only you can enter Eve's dreams...",
  str_guide_warn_80010103 = "Finish the quests detailed in the Memory Fragments to earn Lumamber, and uncover hidden storylines about Eve.",
  str_guide_warn_80010104 = "Metamorpha and Sediment Shards acquired in the Dream can be traded for a range of rewards here, including Eve's outfit.",
  str_guide_warn_80010105 = "The little trinkets collected in the Dream are all carefully stored here by Eve.",
  str_guide_warn_80010106 = "Complete quests in the Dream to acquire the Stand By Me Set.",
  str_guide_warn_80010107 = "Tap here to view details.",
  str_guide_warn_80010202 = "This... seems to be a cup given to me by someone special.",
  str_guide_warn_80010203 = "I remember, this cup can grant me special powers!",
  str_guide_warn_80010204 = "Huh? The cup is empty... I need to collect Ripples of Joy to fill the cup! The more I collect, the more power I can gain!",
  str_guide_warn_80010205 = "But wait... is someone at the door?",
  str_guide_circle_80010206 = "W-What is that?!",
  str_guide_circle_80010207 = "No problem... I'm not afraid! Tap here, I want to go and find out!",
  str_guide_warn_80010208 = "I wonder who it is... Are they coming for me?",
  str_guide_circle_80010304 = "Oh! Found it, is that... the same shadow from earlier?",
  str_guide_warn_80010305 = "That shadow can summon Eclipsites? Now I can't just ignore it, can I?",
  str_guide_warn_80010306 = "My teacher told me that if the enemy is too strong, don't get too caught up in the fight. You can try switching the difficulty level!",
  str_guide_warn_80010307 = "Nightmare is more challenging than Reverie, but if I can clear Nightmare with 3 stars, I could get Ripples of Joy and upgrade Smiles Lead to Happiness.",
  str_guide_warn_80010308 = "Every time I face Omen, my Wit will be affected...",
  str_guide_warn_80010309 = "But no worries! I diligently exercise to stay fit, so at 05:00 every day, the Wit point will recover by 3 points! But once it reaches the maximum limit, it can't be increased any further...",
  str_guide_circle_80010402 = "Found it!",
  str_guide_warn_80010403 = "Anyway, let's put it away for now.",
  str_guide_warn_80010404 = "After collecting so many things, will there be any magical reactions between them?",
  str_guide_warn_80010405 = "Ah... I almost forgot, I still need to go after that shadow!",
  str_guide_warn_80010406 = "Slide the screen to take a good look at the surroundings!",
  str_guide_warn_80010407 = "Tap here to return to the original view.",
  str_guide_warn_80010408 = "There's so much to do, so it's better to keep the information here for now.",
  str_guide_circle_80010501 = "The grown-ups never let me go beyond this gate... so the only way is to break it open if I want to go out?",
  str_guide_circle_80010502 = "We'll find out.",
  str_guide_circle_80011101 = "W-What's that?! Are they trying to wreak havoc in this world... Humph, not like I'll be scared! Tap here, and I'll drive them away in person!",
  str_guide_warn_80010601 = "I've become stronger? The upcoming battles should be a bit easier now.",
  str_guide_warn_80010701 = "I've acquired a completely new ability? I'll give it a try in a bit!",
  str_guide_warn_80010121 = "Huh? What's this?",
  str_guide_warn_80010122 = "Wow, it appears that I have mastered a unique power? Hehe, let's try it out! It seems that it can be used once every other round!",
  str_guide_warn_80010521 = "Eh, my power has changed?",
  str_guide_warn_80010522 = "Choose an area? That doesn't seem difficult. I got you covered!",
  str_guide_warn_80010931 = "Mastered a new power?",
  str_guide_warn_80010932 = "Alright, let's do it!",
  str_guide_warn_80011331 = "My power has changed again...",
  str_guide_warn_80011332 = "It seems I can now unleash this power without any rest...",
  str_guide_warn_80011631 = "I mastered yet another power!",
  str_guide_warn_80011632 = "With this power, I won't hesitate anymore!",
  str_guide_warn_12300101 = "It looks like you're happy with the resort. Can I have a word with you in private then?",
  str_guide_warn_12300201 = "The facilities have produced new Pass Coins again. You need to collect and use them to form a virtuous circle.",
  str_guide_warn_12300202 = "The Pass Coins of the Hotel District are ready for collection. It's an assistant's job to figure out how to use them efficiently.",
  str_guide_warn_12300203 = "You're asking me how Pass Coins are used? Just use them to upgrade facilities directly. Upgraded facilities will also produce Pass Coins at a faster rate. This is how businesses use money to make more money.",
  str_guide_warn_12300204 = "You want to know why you can't collect all Pass Coins at once? This is due to security considerations. The main thing is that it feels most reassuring to pick them up one by one and hold them!",
  str_guide_warn_12300205 = "Do you still remember the way to upgrade facilities? Let's try it out now!",
  str_guide_warn_12300301 = "To upgrade a facility, you need Pass Coins and need to meet certain conditions. Let me see... Yes! This one can be upgraded now.",
  str_guide_warn_12300302 = "Upgraded facilities will become more popular and can produce Pass Coins more efficiently. Upgrading facilities will also unlock adventures with other Aurorians and upgrade rewards.",
  str_guide_warn_12300303 = "Tap here to sign the upgrade plan and complete the upgrade.",
  str_guide_warn_12300401 = "It's been upgraded now! I've also collected the Pass Coins you forgot to collect earlier for you. You're welcome!",
  str_guide_warn_12300501 = "I think you've unlocked adventures with other Aurorians. Let's check it out.",
  str_guide_warn_12300601 = "It looks like a beautiful, intelligent, gentle, and pleasant girl is waiting for you.",
  str_guide_warn_12300701 = "As for how to unlock adventures with Aurorians... I don't think I need to teach you that, right?",
  str_guide_warn_12300801 = "You can view unlocked adventures and review adventures you've already experienced in the Adventure Guide.",
  str_guide_warn_12300802 = "If you have any questions about the operation of the resort, you can check out the handbook I prepared just for you.",
  str_guide_warn_12400101 = "The Valley Oasis event has begun! During the Daytime Attractions, we will explore various facilities within the wonderland.",
  str_guide_warn_12400102 = "During the Night Festivities, we will face more difficult challenges in the amusement park under the cover of darkness.",
  str_guide_warn_12400103 = "In Park Tycoon, we will be responsible for managing the amusement park. Be sure to take good care of it!",
  str_guide_warn_12400104 = "Claw Machine Tokens obtained by completing event stages and spending Prism can be used to redeem various rewards from Claw Machines.",
  str_guide_warn_12400105 = "Remember to log into the game every day to get Guest Sign-in Counter rewards.",
  str_guide_warn_12400106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_12400107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_12500101 = "A Symphony of Gloaming is now available. Let's complete the quest from your Illumina friends in the Twilight Tactics gameplay and rebuild the town!",
  str_guide_warn_12500102 = "In the gameplay On the Cusp of Gloom, we'll dispatch an advance team into the investigation near the twilight zone to find out the Eclipsites' plan!",
  str_guide_warn_12500103 = "Remember to log into the game every day to get New Forces Sign-in rewards.",
  str_guide_warn_12500104 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_12500105 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_10181401 = [[
The durability of the Stronghold Gate is displayed here.
Launch your rockets when the Corrupted Engine VII advances close to the Gate.]],
  str_guide_circle_80010521_Lb = "This is the one holding the doll. When defeated, it deals damage to all Eclipsites on the field and randomly passes on the doll. When other Eclipsites are defeated first, the doll holder gains a count shield.",
  str_guide_circle_80010521_LbT = "Playful Cause",
  str_guide_circle_80010521_Rb = "Unravel illusions with the Doll!",
  str_guide_circle_80010521_RbT = "Tattered Doll",
  str_guide_circle_80010621_Lt = "At the start of the battle, Forest Evil Eyes will be in slumber for 3 rounds, and other Evil Eyes will face a substantial decrease in DEF during this time. Upon being attacked, the Evil Eye will awaken.",
  str_guide_circle_80010621_LtT = "Diligent",
  str_guide_circle_80010621_Lb = "Before we leave, let me take a break...",
  str_guide_circle_80010621_LbT = "Tattered Doll",
  str_guide_circle_80010721_Lt = "If the count shields are not all broken by the end of the round, this enemy deals fixed damage to the player once.",
  str_guide_circle_80010721_LtT = "Narcissistic Rage",
  str_guide_circle_80010721_Rt = "Is this... the only way to get your attention?",
  str_guide_circle_80010721_RtT = "Tattered Doll",
  str_guide_circle_80010821_Lt = "The boss gathers energy every 3 rounds. Each stack of energy grants a 3% ATK bonus. If all the stacks are not removed by the end of the round, the boss will acquire 8 stacks of count shield.",
  str_guide_circle_80010821_LtT = "Iron Grasp",
  str_guide_circle_80010821_Rt = "Break through... the cage... just to... wake you up...",
  str_guide_circle_80010821_RtT = "Tattered Doll",
  str_guide_circle_80010821_Rb = "Each time the boss is attacked, 1 stack of the mark will be removed. These energy marks significantly enhance the boss' ATK and survivability, so dealing with them as quickly as possible is crucial!",
  str_guide_circle_80010821_RbT = "Coping Strategy",
  str_guide_circle_80011021_Rt = "All enemies gain a significant boost in ATK. Aurorians can restore their HP by consistently inflicting damage on enemies.",
  str_guide_circle_80011021_RtT = "Mortal Counterattack",
  str_guide_circle_80011021_Rb = "What's the difference between stopping and giving up?",
  str_guide_circle_80011021_RbT = "\"Eve\"",
  str_guide_circle_80011121_Rt = "The team can use the Conveyor Vortex to teleport anywhere on the field and launch Chain Combos. Increases Chain Combo damage.",
  str_guide_circle_80011121_RtT = "Free Combo",
  str_guide_circle_80011121_Rb = "Come with me. You can go anywhere you want.",
  str_guide_circle_80011121_RbT = "\"Eve\"",
  str_guide_circle_80011421_Rt = "The generation of runes is inefficient, and the Shadow will now directly summon Shadowgeists.",
  str_guide_circle_80011421_RtT = "Enemy Characteristics",
  str_guide_circle_80011421_Rb = "While connecting tiles, Aurorians' damage dealt will be greatly increased, including normal attacks and additional damage effects.",
  str_guide_circle_80011421_RbT = "Team Characteristics",
  str_guide_circle_80011521_Rt = "Defeat Enferno to clear the stage. Spellhound will keep respawning before Enferno is defeated.",
  str_guide_circle_80011521_RtT = "Enemy Characteristics",
  str_guide_circle_80010921_Lb = "All the Eclipsites present can respawn once. When an Eclipsite dies, all remaining Eclipsites on the field receive an increase in ATK.",
  str_guide_circle_80010921_LbT = "Enemy Characteristics",
  str_guide_circle_80010921_Rb = "The harder you struggle, the more it hurts.",
  str_guide_circle_80010921_RbT = "\"Eve\"",
  str_guide_circle_80011321_Lb = "The number of Penetrability Mark stacks will increase significantly with enemy skills, but each player attack will reduce the Penetrability Mark by one stack.",
  str_guide_circle_80011321_LbT = "Enemy Characteristics",
  str_guide_circle_80011321_Rb = "Penetrability Marks' negative effect is greatly increased. Ensure to reduce the number of Penetrability Marks by attacking the enemy as quickly as possible!",
  str_guide_circle_80011321_RbT = "Coping Strategy",
  str_guide_circle_80011621_Lb = "Starting from this stage, the team gains special entries. Each time the enemy takes damage before the team connects tiles, the attack of all Aurorians in the team increases by 1% for that round!",
  str_guide_circle_80011621_LbT = "The Last Growth",
  ["str_guide_circle_CN2-18_Lt"] = "The pain of isolation and the fear of being severed, those unbearable memories of the past, have shaped the person known as Eve today.",
  ["str_guide_circle_CN2-18_LtT"] = "Grieving Eve",
  ["str_guide_circle_CN2-18_Rt"] = "At the start of each round, summon a Dawn Flower at a set location to restore HP; each Dawn Flower grants an extra recovery boost.",
  ["str_guide_circle_CN2-18_RtT"] = "Enemy Characteristics",
  ["str_guide_circle_CN2-18_Rb"] = "In specific rounds, Eve will receive a large number of immunity stacks. It's essential to reduce these stacks as much as possible through high-frequency damage; otherwise, in the next round, a substantial amount of HP will be restored based on the remaining number of stacks.",
  ["str_guide_circle_CN2-18_RbT"] = "Skill Description",
  str_guide_circle_N34_18_1_RtT = "Illumina Medic",
  str_guide_circle_N34_18_1_Rt = "Wherever the Illumina Medic stands, morale elevates, for comrades know that their injuries won't be left untreated. The Illumina Federation, well aware of this fact, provides these medics with enhanced protection, significantly augmenting their survival capabilities.",
  str_guide_circle_N34_18_1_LbT = "Monster Traits",
  str_guide_circle_N34_18_1_Lb = "An Illumina Soldier without combat capabilities. Restores HP for a nearby Illumina Soldier and restores a certain portion of their own Bruise.",
  str_guide_circle_N34_18_1_RbT = "Watch out!",
  str_guide_circle_N34__18_1_Rb = "When taking damage, Illumina Medic will accumulate Bruises equal to 50% of the damage received. Additionally, their DEF increases as their HP declines.",
  str_guide_circle_N34_18_2_RtT = "Illumina Signalman",
  str_guide_circle_N34_18_2_Rt = "Equipped with a compact communicator, the Illumina Signalman bears a heavy load. Thus, the Illumina Federation has engineered a specialized support apparatus, facilitating their signal transmission on the move, which is the origin of this unit's name.",
  str_guide_circle_N34_18_2_LbT = "Monster Traits",
  str_guide_circle_N34_18_2_Lb = "An Illumina Soldier without combat capabilities but able to summon Illumina reinforcements into the battlefield.",
  str_guide_circle_10170901_RtT = "Dreadweaver",
  str_guide_circle_10170901_Rt = "Driven by an obsession to annihilate all, it disregards the depletion of its own energy, relentlessly pursuing the goal, even if it means gradually marching toward its own demise.",
  str_guide_circle_10170901_LbT = "Passive Details",
  str_guide_circle_10170901_Lb = "Every time the team's movement ends, Dreadweaver will immediately have the team change their positions, affecting the casting of Chain Combos.",
  str_guide_circle_10170901_RbT = "Attack Characteristics",
  str_guide_circle_10170901_Rb = "When Dreadweaver's HP drops below 50%, it will initiate a sacrificial ritual. In the next round, it will burn down almost all of its HP, dealing massive true damage to players. This effect can only be triggered once.",
  str_guide_circle_2002901_RtT = "Illumina L5 Tank",
  str_guide_circle_2002901_Rt = "Crafted through truck modifications, the Illumina L5 Tank features lightweight armor, rendering it perfect for mass manufacturing. Its charging prowess and rapid-firing cannons make short work of enemy light units.",
  str_guide_circle_2002901_LbT = "Enemy Characteristics",
  str_guide_circle_2002901_Lb = "Based on enemy positions, opts for either firing a rapid barrage of shots or a charging rush for attack.",
  str_guide_circle_2003001_RtT = "Illumina Flamethrower",
  str_guide_circle_2003001_Rt = "\"Reduce all adversaries to ashes\"—They epitomize the efficiency and ruthlessness of the Illumina forces. Before the raging flames, all life stands on an even footing.",
  str_guide_circle_2003001_LbT = "Enemy Characteristics",
  str_guide_circle_2003001_Lb = "Accumulates Bruises while receiving damage. Deals damage to all targets within the range of attack, inflicting Burn on them and creating fires.",
  str_guide_circle_2003401_RtT = "Corrupted Illumina Soldier",
  str_guide_circle_2003401_Rt = "Once allies, now enemies—such is the dread of the Eclipse. The only mercy left is to lay them to rest.",
  str_guide_circle_2003401_LbT = "Enemy Characteristics",
  str_guide_circle_2003401_Lb = "If HP is below 40% at the start of a round, the unit has its ACT and DEF increased and its attack style altered.",
  str_guide_circle_2003101_RtT = "Illumina Sergeant",
  str_guide_circle_2003101_Rt = "As the grassroots officers of the Illumina army, they are responsible for commanding regular soldiers on the battlefield. Most of them graduate from military academies, while a select few are promoted from the ranks of experienced veterans.",
  str_guide_circle_2003101_LbT = "Enemy Characteristics",
  str_guide_circle_2003101_Lb = "Their presence enhances the abilities of nearby Illumina Soldiers and helps them recover from their Bruises. Should they find themselves isolated from allies or in close quarters with foes, these sergeants take up arms, dealing damage with devastating cuts and impactful kicks.",
  str_guide_circle_2003101_RbT = "Coping Strategy",
  str_guide_circle_2003101_Rb = "Defeat the enemy's commander first!",
  str_guide_circle_2905701_RtT = "Mudbundle",
  str_guide_circle_2905701_Rt = "Rumored to be a creation of an Eclipse member, this Eclipsite is a fusion of various biological traits. It creates terrifying quagmires that can devour everything and contaminate all it touches.",
  str_guide_circle_2905701_LbT = "Enemy Characteristics",
  str_guide_circle_2905701_Lb = "Creates quagmires and submerges within, obstructing and disrupting Aurorians' movements within, altering the terrain.",
  str_guide_circle_2905701_RbT = "Coping Strategy",
  str_guide_circle_2905701_Rb = "Avoid passing through too many quagmires. Use your skills to clean the field!",
  str_guide_circle_29057011_RtT = "Quagmire",
  str_guide_circle_29057011_Rt = "Contaminating all it has seen...",
  str_guide_circle_29057011_LbT = "Characteristics",
  str_guide_circle_29057011_Lb = "Passing through a certain number of mires will increase the cooldown of all Aurorians' Active Skills.",
  str_guide_circle_29057011_RbT = "Coping Strategy",
  str_guide_circle_29057011_Rb = "Can be cleaned by Aurorians' Area Damage Skills",
  str_guide_warn_815000101 = [[
Why am I still not able to break free from this dream? Is it because of Paloma... is she still trapped within it?
Tap the Switch button to switch to the Roam Mode. Navigator, can you help out Paloma like the way you helped me?]],
  str_guide_warn_815000102 = "Tap the Switch button again to switch back to Unveil Mode. Navigator, it seems we can return to my dream anytime we want!",
  str_guide_circle_80020201 = "Tap the scale here to help me delve into more profound contemplation and deduction. Only after completing my deductions can I continue with the tasks assigned by the Chief Judge.",
  str_guide_circle_80020202 = "However, before starting the deduction, I have to gather enough evidence, testimonials... Observe closely. Crucial clues must be nearby!",
  ["str_guide_circle_CN5-15_Lt"] = "Inheriting her father's earnest teachings and fulfilling all his expectations, she has become the perfect Irridon, the greatest Chief Judge ever known!",
  ["str_guide_circle_CN5-15_LtT"] = "Irridon: Eximius",
  ["str_guide_circle_CN5-15_Rt"] = "Before each Chain Combo, forms Shield of Light, blocking damage equal to a percentage of Max HP.",
  ["str_guide_circle_CN5-15_RtT"] = "Shield of Light",
  ["str_guide_circle_CN5-15_Lb"] = "Manipulating and deceiving others with her clones—these tricks are hardly dishonorable in her eyes; after all, she holds the ultimate authority as the greatest Chief Judge.",
  ["str_guide_circle_CN5-15_LbT"] = "Irridon: Eximius Clone",
  ["str_guide_circle_CN5-15_Rb"] = "Damage dealt to Irridon: Eximius Clones is instantly transferred to Irridon: Eximius.",
  ["str_guide_circle_CN5-15_RbT"] = "Damage Transmission",
  ["str_guide_circle_CN5-18_Lb"] = "Situated off-field, immune to normal attacks, can only be attacked by single-target skills.",
  ["str_guide_circle_CN5-18_LbT"] = "Irridon: Eximius Clone",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "Arrogant noble statue. It inflicts 1 stack of Prejudice on allies and crumbles upon touch, transforming the tile they were at into a chromatic tile while removing 1 stack of Prejudice.",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "Juror Statue",
  ["str_guide_circle_CN5-4_Rb"] = "Specific enemies possess the Shield of Light effect. Before each Chain Combo, they form Shield of Light, blocking damage equal to a percentage of their Max HP.",
  ["str_guide_circle_CN5-4_RbT"] = "Shield of Light",
  ["str_guide_circle_CN5-8_Lt"] = "Arrogance, prejudice, and corrupted thoughts... have congealed into malevolent specters wandering in Lumopolis, seeping into every crevice of this eternal city.",
  ["str_guide_circle_CN5-8_LtT"] = "Crimson Specter",
  ["str_guide_circle_CN5-8_Lb"] = "It can teleport to the nearest player's location, delivering multiple damaging blows and knocking the player back. The farther it teleports, the fewer attacks it launches.",
  ["str_guide_circle_CN5-8_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_CN5-8_Rb"] = "The Crimson Specter can disrupt players' positions, so it's advisable to either eliminate it promptly or move away from it.",
  ["str_guide_circle_CN5-8_RbT"] = "Coping Strategy",
  ["str_guide_circle_n35-7_LtT"] = "Rimebeast",
  ["str_guide_circle_n35-7_Lt"] = "With fur and sharp claws, this kind of Eclipsites bears an uncanny resemblance to savage beasts, making them well-suited for infiltrating various border regions for tracking, scouting, and hunting.",
  ["str_guide_circle_n35-7_Lb"] = "It selects different skills based on the Aurorian's position, and if its attack cannot reach any Aurorians, it will choose to recover its own HP.",
  ["str_guide_circle_n35-7_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_n35-7_Rb"] = "Keep an eye on the Eclipsite's attack range, and always be mindful of our ally's position!",
  ["str_guide_circle_n35-7_RbT"] = "Coping Strategy",
  ["str_guide_circle_n35-9_LtT"] = "No. 33",
  ["str_guide_circle_n35-9_Lt"] = "An Aurorian from the distant past, charged with guarding Northland's underground ruins. Her Echo Template keeps producing errors due to the damage she's sustained and her unorthodox activation.",
  ["str_guide_circle_n35-9_Lb"] = "Able to teleport and disrupt the layout of the tiles as well as absorb tile energy to attack Aurorians. The more tiles available to absorb energy from, the higher the damage.",
  ["str_guide_circle_n35-9_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_n35-9_Rb"] = "Pay attention to the distribution of tiles on the battlefield and watch out for when the enemy uses skills!",
  ["str_guide_circle_n35-9_RbT"] = "Coping Strategy",
  str_guide_circle_n35_trap5352031_RtT = "Fatal Bomb",
  str_guide_circle_n35_trap5352031_Rt = "Explodes whenever a certain amount of time has elapsed, dealing damage to all units on the battlefield.",
  str_guide_circle_n35_trap5352031_RbT = "Coping Strategy",
  str_guide_circle_n35_trap5352031_Rb = "Command your Aurorians to defeat the enemies ASAP, or you'll take damage over time.",
  str_guide_warn_53540034 = "Displayed here is the remaining countdown for the Realm.",
  str_guide_warn_16000101 = [[
An Enigma Sealed in Ice is now available!
Time to meet new partners and embark on the adventure in the Through the Snow expedition!]],
  str_guide_warn_16000102 = "In Fatal Trek, we'll face a series of more complex challenges.",
  str_guide_warn_16000103 = "In the Ancient Yurt event, we can exchange Ancient Remains for Solamber, 5-star Aurorians, and other valuable items. Ancient Remains can be obtained by completing event stages and consuming Prism.",
  str_guide_warn_16000104 = "New Zarya's Closet gameplay will be available soon. Access it via the event interface to participate!",
  str_guide_warn_16000105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_16000106 = "Remember to log into the game every day to get daily sign-in rewards.",
  str_guide_warn_16000107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_9700101 = "The Wishlist is available in this limited-time recruitment. Tap to open the Wishlist interface.",
  str_guide_warn_9700106 = "The Wishlist is exclusively available in the recruitment it belongs to.",
  str_guide_warn_9700107 = "In this recruitment, there's an Aurorian featuring an increased obtaining probability that is fixed at the top spot of the Wishlist, taking up a 50% chance in all 6-star Aurorians available.",
  str_guide_warn_9700108 = "Select one 6-star Aurorian from each of the four elements, and each of them will take up a 12.5% chance of obtaining 6-Star Aurorians.",
  ["str_guide_circle_n36-9_LtT"] = "Emperor of Demise",
  ["str_guide_circle_n36-9_Lt"] = "The Supreme Emperor of Chaos, Tohru's father, a veteran of many wars, is an undeniable powerhouse no matter when and where.",
  ["str_guide_circle_n36-9_Lb"] = "With formidable strength, he wields a multitude of skills to target players with precision or unleash wide-ranging attacks, while knocking them back.",
  ["str_guide_circle_n36-9_LbT"] = "Enemy Characteristics",
  ["str_guide_circle_n36-9_Rb"] = "The Emperor of Demise can be influenced by the knockback or teleportation skills of the player. Displacing him at the right moment enables the player to evade or interrupt his attack skills.",
  ["str_guide_circle_n36-9_RbT"] = "Coping Strategy",
  str_guide_warn_17000101 = "Dragon Maid's Break is now available! Time to meet new friends and embark on a new adventure in The Road Home!",
  str_guide_warn_17000102 = "Spend Prism in main stages and Resource Raid stages for Dinner Plates.",
  str_guide_warn_17000103 = "Use Dinner Plates to receive a variety of rewards in Tohru's Kitchen.",
  str_guide_warn_17000104 = "During the event, join A Caelestite Tea Party for rapport quizzes with Aurorians!",
  str_guide_warn_17000105 = "Remember to log into the game every day to get sign-in rewards.",
  str_guide_warn_17000106 = "Take on a range of event challenges and complete the quests in your Special Event Book!",
  str_guide_warn_17000107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_18000101 = "Venom Flows Through Corrupted Hearts is now available! Time to meet new friends and embark on a new adventure in the Underground Clinic!",
  str_guide_warn_18000102 = "In Bleak Past, we'll face a series of more complex challenges.",
  str_guide_warn_18000103 = "Completing event stages and spending Prism grants Collection Jars which can be used to redeem various rewards from The Secret Room.",
  str_guide_warn_18000104 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_18000105 = "Remember to log into the game every day to get daily sign-in rewards.",
  str_guide_warn_18000106 = "If you have any questions about the event, you can view the detailed description here.",
  ["str_guide_circle_CN7-15_Lt"] = "From the surface world to the underwater town, a domineering and villainous noble.",
  ["str_guide_circle_CN7-15_LtT"] = "Merman King",
  ["str_guide_circle_CN7-15_Rt"] = "Attacks inflict knockback. Can summon salvo guns at the edge of the battlefield.",
  ["str_guide_circle_CN7-15_RtT"] = "Enemy Characteristics",
  ["str_guide_circle_CN7-15_Lb"] = "Pay attention to the attack range of the salvo guns around the battlefield. Defeat the artillery in a timely manner to quickly end the battle.",
  ["str_guide_circle_CN7-15_LbT"] = "Coping Strategy",
  ["str_guide_circle_CN7-5_Lt"] = "An Eclipsite that resembles a gun barrel. Provides support to its companions and attacks your team heavily!",
  ["str_guide_circle_CN7-5_LtT"] = "Salvo Gun",
  ["str_guide_circle_CN7-5_Rt"] = "Fires upon enemies within attack range. If no targets are available, its attack is enhanced and it heals the Merman King.",
  ["str_guide_circle_CN7-5_RtT"] = "Heavy Cannon",
  ["str_guide_circle_CN7-7_Lt"] = "Allies cannot connect through it, and neither can enemy ground units, but this won't affect the effect of any skills cast.",
  ["str_guide_circle_CN7-7_LtT"] = "Forbidden Wall",
  str_guide_circle_80030101 = "With binoculars, you can see the grand castle in the distance—the temple of the Aqua Lord.",
  str_guide_warn_80030102 = "Tap the Temple Construction button and Connolly will head to a place with a perfect view of the temple, along with her trusty tentacles, to continue the temple restoration project.",
  str_guide_warn_80030301 = "Navigator, welcome to the Fusion Ritual! Place the Aqua Shard in the fusion area at the center of the Fusion Ritual to assist me in completing the ritual, restoring Antons' strength!",
  str_guide_warn_80030302 = "The Aqua Shard contains the power of Anton. Each Shard features a different amount of fusion power. Under specific conditions, some shards might release additional power.",
  str_guide_warn_80030303 = "Drag the Aqua Shard to an eligible spot in the fusion area. Once it's successfully placed, the Fusion Ritual will guide and extract the fusion power within.",
  str_guide_warn_80030304 = "After successfully placing the Aqua Shard, you can tap to select and move or adjust it. Explore different placements to draw out more aggregation power.",
  str_guide_warn_80030305 = "While selected, tap the Rotate button to rotate the shard counterclockwise by 90 degrees.",
  str_guide_warn_80030306 = "While selected, tap the Cancel button to take the shard back.",
  str_guide_warn_80030307 = "Here, you'll find the total fusion power contained in the currently placed Aqua Shards and the fusion power required to complete this Fusion Ritual!",
  str_guide_warn_80030308 = "Tap the Clear button to remove all placed Aqua Shards. Do exercise caution!",
  str_guide_warn_80030309 = "When the fusion power meets the requirements for the Fusion Ritual, tap the Complete button to finish the ritual and restore Anton's strength!",
  str_guide_warn_18100101 = "Please help take a look with me! What in the world is going on here!",
  str_guide_warn_18100102 = "This is where you can start your training! Complete training stages to earn points and stage rewards!",
  str_guide_warn_18100103 = "Please Note: During the training module, bonds exist between certain Aurorians. When Aurorians with a bond are deployed at the same time, they will gain more opportunities to engage in combat.",
  str_guide_warn_18100104 = "When at least 3 Aurorians of a designated faction are deployed, removing multiple tiles at once during training can activate faction support skills.",
  str_guide_warn_18100105 = "Completing the training will earn you points, and once you reach a specified number of points per session, you'll get special rewards.",
  str_guide_warn_18100106 = "Completing training stages will earn you rewards. The maximum amount of rewards you can obtain each session will be displayed here.",
  str_guide_warn_18100107 = "If you have any questions, you can view the detailed description here.",
  str_guide_warn_18100108 = "The total number of rounds in each training cycle is limited, and the total HP of teams from stage to stage will carry over.",
  str_guide_circle_N37boss_Lt = "Her veins pulsate with crimson venom, ready to eradicate any threat to her family, including herself.",
  str_guide_circle_N37boss_LtT = "Rebecca Venomswamp",
  str_guide_circle_N37boss_Rt = "Inflicts the Fusion effect, causing affected targets to lose HP at the beginning of their rounds.",
  str_guide_circle_N37boss_RtT = "Enemy Characteristics",
  str_guide_circle_N37boss_Lb = "Make full use of the Dark Tiles turned by Poison Marks and deal damage at the right moment.",
  str_guide_circle_N37boss_LbT = "Coping Strategy",
  str_guide_circle_N37cap_Lt = "The peculiar-looking leader of a gang, skilled in firearms. His presence spells nothing but trouble for Umbraton.",
  str_guide_circle_N37cap_LtT = "Gang Captain",
  str_guide_circle_N37cap_Rt = "Attacks after moving away from the target, dealing damage 2 times. Can steal the target's attributes.",
  str_guide_circle_N37cap_RtT = "Enemy Characteristics",
  str_guide_circle_N37cap_Lb = "Pay attention to the distance in between and defeat enemies timely.",
  str_guide_circle_N37cap_LbT = "Coping Strategy",
  str_guide_circle_N37ranger_Lt = "Accurate, safe, discreet, and incredibly powerful, crossbows have become a beloved weapon among gangsters due to these unparalleled properties. Enemies adept in its use are often highly dangerous.",
  str_guide_circle_N37ranger_LtT = "Gang Crossbowman",
  str_guide_circle_N37ranger_Rt = "Can attack targets in a cross shape to the maximum extent of its range. After hitting, reduces the target's healing received.",
  str_guide_circle_N37ranger_RtT = "Enemy Characteristics",
  str_guide_circle_N37ranger_Lb = "Close in swiftly and prioritize eliminating them.",
  str_guide_circle_N37ranger_LbT = "Coping Strategy",
  str_guide_circle_N37light_Lt = "A hulking gang member of immense strength, skilled in using his mechanical arms for combat. Moreover, he can offer support to other enemy forces of Umbraton in the field.",
  str_guide_circle_N37light_LtT = "Gang Support Specialist",
  str_guide_circle_N37light_Rt = "Provides an ATK boost to Umbraton members within 1 surrounding cluster; heals self when their HP falls below a certain percentage.",
  str_guide_circle_N37light_RtT = "Enemy Characteristics",
  str_guide_circle_N37light_Lb = "Eliminate them in one go to prevent their continuous self-healing.",
  str_guide_circle_N37light_LbT = "Coping Strategy",
  str_guide_circle_n37_trap2803501_RtT = "Dark Tile",
  str_guide_circle_n37_trap2803501_Rt = "The next tile at this location is guaranteed to be the same element as the current tile.",
  str_guide_circle_n37_trap2803501_RbT = "Coping Strategy",
  str_guide_circle_n37_trap2803501_Rb = "Use tile-converting skills to convert tiles' elements to maximize their effects.",
  str_guide_circle_N37cike_LtT = "Gang Assassin",
  str_guide_circle_N37cike_Lt = "Launches 2 rapid consecutive strikes against the enemy and steals the target's attributes.",
  str_guide_circle_N37cike_Lb = "Defeat the enemies as quickly as possible. Don't let them attack you continuously.",
  str_guide_circle_N37cike_LbT = "Coping Strategy",
  str_guide_warn_551105 = "Tap here!",
  str_guide_warn_551106 = "The Enlightenment system has been activated. Aurorian attributes can now be comprehensively enhanced. Tap to enter the Water Module.",
  str_guide_warn_551107 = "The list on the left allows you to quickly switch between Modules of different Elements.",
  str_guide_warn_551108 = "View the level and progress of this Element Module here.",
  str_guide_warn_551109 = "View Module upgrade details here.",
  str_guide_warn_551110 = "If you have any questions, you can view the detailed description here.",
  str_guide_warn_19000101 = "Here, you can salvage treasures, bringing precious relics from the sunken ships back to the surface one by one.",
  str_guide_warn_19000102 = "The found relics will be documented in this Relic Archive. Open it to access related records.",
  str_guide_warn_19000103 = "If you have any questions, feel free to check the help instructions here for clarification.",
  str_guide_warn_19000104 = "Tap on the relics in the field to move them to the salvage area below.",
  str_guide_warn_19000105 = "When the number of identical relics in the salvage area reaches 3, the relic will be successfully salvaged and removed from the slots.",
  str_guide_warn_19000106 = "Here, use the relic storage function to move relics from the salvage slots to the field, preventing failure because all slots are filled.",
  str_guide_cage_Rt = "Can be smashed by Aurorians' Area Damage Skills. New enemies may appear after it is smashed!",
  str_guide_cage_RtT = "Special Trap - Cage",
  str_guide_circle_N38boss_Lt = "A dangerous weapon created by combining the deadly characteristics of many mechanical creations, including technology from Astra. Ordinary power sources are unable to keep this giant creature going.",
  str_guide_circle_N38boss_LtT = "Stinger: Coalescence",
  str_guide_circle_N38boss_Rt = "Each Clockwork Beast that forms a part of its body has its own unique attack. The tail can gather Energy to deal guaranteed damage to its targets, but it is also relatively fragile.",
  str_guide_circle_N38boss_RtT = "Enemy Characteristics",
  str_guide_circle_N38boss_Lb = "Attack its tail with Sniper Aurorians first to make it temporarily unable to move, then take this opportunity to dish out damage.",
  str_guide_circle_N38boss_LbT = "Coping Strategy",
  str_guide_warn_13800101 = [[
Etched Upon the Ocean Drifting Begonia I is now available!
Time to meet new friends and embark on a new adventure in The Homecoming!]],
  str_guide_warn_13800102 = "Spend Prism in main story stages and Resource Raid stages for Lin Guild Promissory Notes.",
  str_guide_warn_13800103 = "In Lost Ship At Sea, we'll face a series of more complex challenges.",
  str_guide_warn_13800104 = "In The Docks, use Lin Guild Promissory Notes to redeem various rewards.",
  str_guide_warn_13800105 = "Remember to log into the game every day to get Berth Sign-In rewards.",
  str_guide_warn_13800106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_13800107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_crab_Rt = "This mechanical tool creation was designed to help craftsmen make ingenious inventions. Later, it was modified so that a variation of this invention could store Flame Force in its belly. It was never intended to be used as a weapon.",
  str_guide_crab_RtT = "Furnace-Forged Crab",
  str_guide_crab_Lt = "Moves laterally while spitting out flames to attack targets in front of it.",
  str_guide_crab_LtT = "Enemy Characteristics",
  str_guide_crab_Lb = "The Furnace-Forged Crab has a fixed movement pattern and can't turn around, so get behind it before you start dishing out damage.",
  str_guide_crab_LbT = "Coping Strategy",
  str_guide_warn_13900101 = [[
Shadows Beneath the Gloom is now available!
Time to meet new friends and embark on a new adventure in the Under the Shadows!]],
  str_guide_warn_13900102 = "Spend Prism in main story stages and Resource Raid stages for Cloudrover Tokens.",
  str_guide_warn_13900103 = "In Deadly Arena, we'll face a series of more complex challenges.",
  str_guide_warn_13900104 = "In Cloudrover Airship, use Cloudrover Tokens to redeem various rewards.",
  str_guide_warn_13900105 = "Remember to log into the game every day to get Visitor Sign-In rewards.",
  str_guide_warn_13900106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_13900107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_circle_S4boss_Lt = "A deftly crafted sword born from the ingenuity of the Ye Kingdom of Longzhou. It was originally intended as a self-defense weapon for those who did not know how to defend themselves with a sword, but has now become a cursed evil sword after falling into the hands of villains.",
  str_guide_circle_S4boss_LtT = "Vilanor: Cursed Trap",
  str_guide_circle_S4boss_Rt = "After becoming Vilanor, its abilities are greatly enhanced, gaining the power to move freely through the field and generate swords out of evil energy.",
  str_guide_circle_S4boss_RtT = "Enemy Characteristics",
  str_guide_circle_S4boss_Lb = "Vilanor has the ability to cut open space and create Forbidden Walls, so you can use Aurorians who have teleport abilities to step on Exorcism Traps and attack Vilanor easily after removing the Forbidden Walls.",
  str_guide_circle_S4boss_LbT = "Coping Strategy",
  str_guide_warn_16021911 = "It's necessary to select 1 ally or Shadow Piece to use Istvan: Scarred Pith's Active Skill.",
  str_guide_warn_16021912 = "This is where you can see the number of Shadow Endowments used by the current ally. It can't be cast on this ally if an insufficient number has been used.",
  str_guide_warn_16021913 = "Cast the skill on Areia.",
  str_guide_warn_16021914 = "In this battle, this skill's cost +1 whenever an Active Skill is cast on this ally.",
  str_guide_warn_80040111 = "Navigator, look over here! You've gained a new ability in the Dream!",
  str_guide_warn_80040112 = "Your abilities will get stronger as you venture deeper into dreams. Make good use of them!",
  str_guide_circle_shenghuaboss_Lt = "This super soldier is an Eclipsite that has been equipped with mechanical devices all over its body to make it tougher, more ferocious, and more intimidating.",
  str_guide_circle_shenghuaboss_LtT = "Super-Soldier Blaugm",
  str_guide_circle_shenghuaboss_Rt = "An intimidating super soldier that excels at crushing nearby enemies with its attacks.",
  str_guide_circle_shenghuaboss_RtT = "Enemy Characteristics",
  str_guide_circle_shenghuaboss_Lb = "Blaugm has high resistance to Normal Attack damage, so try to deal damage with Chain Combos or Active Skills.",
  str_guide_circle_shenghuaboss_LbT = "Coping Strategy",
  str_guide_circle_ylxs_Lt = "Ulysses modified his body extensively to realize his extreme ideals. He is no longer an Aurorian now.",
  str_guide_circle_ylxs_LtT = "Ulysses Bio",
  str_guide_circle_ylxs_Rt = "Ulysses uses different attack strategies based on the abilities of the Aurorians.",
  str_guide_circle_ylxs_RtT = "Enemy Characteristics",
  str_guide_circle_ylxs_Lb = "Based on the team's current condition, attack wisely and avoid taking damage from Ulysses to greatly increase the chance of victory.",
  str_guide_circle_ylxs_LbT = "Coping Strategy",
  str_guide_warn_shzyx_01 = "Warning! The Guardian Prototype has been activated.",
  str_guide_warn_shzyx_02 = "This ancient machine built by the Engineer seems to be self-aware.",
  str_guide_warn_shzyx_03 = "Restricts Aurorians' Normal Attacks, Active Skills, or Chain Combos. It also damages enemies and protects allies at the same time.",
  str_guide_warn_shzyx_04 = "Based on the team's current condition, attack wisely to have a chance of going toe to toe with it. Don't underestimate it!",
  str_guide_circle_soilder1_Rt = "A war weapon created through the fusion of Eclipsites and Aurorians. The characteristics of Aurorians have been retained as much as possible, and the mechanization is not too obvious, but it is still very dangerous.",
  str_guide_circle_soilder1_RtT = "Soldier Voidcross",
  str_guide_circle_soilder1_Rb = "A mechanical life form that attacks by hacking and slashing.",
  str_guide_circle_soilder1_RbT = "Enemy Characteristics",
  str_guide_circle_soilder1_Lb = "Soldier Voidcross can reflect Aurorians' Normal Attack damage. Keep your distance and try to deal damage with Chain Combos or Active Skills.",
  str_guide_circle_soilder1_LbT = "Coping Strategy",
  str_guide_circle_soilder2_Rt = "A war weapon created through the fusion of Eclipsites and Aurorians. It is protected by a thick layer of mechanical armor, and its strength has been enhanced to the greatest extent possible.",
  str_guide_circle_soilder2_RtT = "Soldier Ululat",
  str_guide_circle_soilder2_Rb = "This modified mechanical life form's power and defense have been improved greatly, and it excels at attacking with explosions and other similar methods.",
  str_guide_circle_soilder2_RbT = "Enemy Characteristics",
  str_guide_circle_soilder2_Lb = "Soldier Ululat can reflect Aurorians' Normal Attack damage. Pay attention to the attack range and try to deal damage with Chain Combos or Active Skills.",
  str_guide_circle_soilder2_LbT = "Coping Strategy",
  str_guide_circle_soilder3_Rt = "A super weapon created through the fusion of Eclipsites and Aurorians. It no longer has Aurorian characteristics and is now a fully mechanical existence.",
  str_guide_circle_soilder3_RtT = "Super-Soldier Meaugm",
  str_guide_circle_soilder3_Rb = "This modified mechanical life form can use its thick armor as a weapon, making it very tough to handle.",
  str_guide_circle_soilder3_RbT = "Enemy Characteristics",
  str_guide_circle_soilder3_Lb = "Super-Soldier Meaugm can reflect Aurorians' Normal Attack damage and restore its own HP, so try to end the battle as quickly as possible.",
  str_guide_circle_soilder3_LbT = "Coping Strategy",
  str_guide_warn_14000101 = [[
Through the Mist, Echoes from the Past is now available!
Let's start a new story in Part 2!]],
  str_guide_warn_14000102 = "Story chapters that are unlocked in this event, as well as chapters that have been explored so far, are displayed here.",
  str_guide_warn_14000103 = "Tap Explore Now to go directly to the Explore map. Spend Prism in main story stages and Resource Raid stages for Caelestite Feathers.",
  str_guide_warn_14000104 = "In Aurora Exchange, use Caelestite Feathers to redeem various rewards.",
  str_guide_warn_14000105 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_14000106 = "Remember to log into the game every day to get Navigation Sign-In rewards.",
  str_guide_warn_14000107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_14100101 = "Drifting Begonia II: Cometh the Dragon, Spirits Begone is now available! Time to meet new friends and embark on a new adventure in Dragon's Dance!",
  str_guide_warn_14100102 = "Spend Prism in main story stages and Resource Raid stages for Prayer Incense.",
  str_guide_warn_14100103 = "In Absconding Evil, we'll face a series of more complex challenges.",
  str_guide_warn_14100104 = "In Sea Blessings, use Prayer Incense to redeem various rewards.",
  str_guide_warn_14100105 = "Remember to log into the game every day to get Visitor Sign-In rewards.",
  str_guide_warn_14100106 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_warn_14100107 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_circle_yingzi_LtT = "Evil Will: Shadow",
  str_guide_circle_yingzi_Lt = "Tainted by Evil Will, its summoning powers have subtly changed.",
  str_guide_circle_yingzi_RtT = "Enemy Characteristics",
  str_guide_circle_yingzi_Rt = "The number of runes summoned each time increases significantly.",
  str_guide_circle_miran_LtT = "Evil Will: Murkmite",
  str_guide_circle_miran_Lt = "Tainted by Evil Will, its attacks have subtly changed.",
  str_guide_circle_miran_RtT = "Enemy Characteristics",
  str_guide_circle_miran_Rt = "Upon hits, its attack immediately reduces the player's Force Point by 2.",
  str_guide_circle_aogeyang_LtT = "Evil Will: Augean",
  str_guide_circle_aogeyang_Lt = "Tainted by Evil Will, its ability has subtly changed.",
  str_guide_circle_aogeyang_RtT = "Enemy Characteristics",
  str_guide_circle_aogeyang_Rt = "Gains a significant boost in mobility and, every 2 rounds, summons monsters to the nearby area to attack the player together.",
  str_guide_circle_jingmianta_LtT = "Reflector Tower: Vitalized",
  str_guide_circle_jingmianta_Lt = "Mirror device that transforms in special environments, offering assistance to Aurorian teams.",
  str_guide_circle_jingmianta_RtT = "Trap Characteristics",
  str_guide_circle_jingmianta_Rt = "Positioning on the field provides special energy to the team, Force Point recovery per round +1.",
  str_guide_circle_laolong_LtT = "Evil Will: Cage",
  str_guide_circle_laolong_Lt = "Within the cage are enemies imprisoned for particular reasons. Once set free, they may be a help to the Boss or expose the Boss' vulnerability.",
  str_guide_circle_laolong_RtT = "Trap Characteristics",
  str_guide_circle_laolong_Rt = "Tap the trap and spend 3 Force Points to release enemies from the cage. Though they won't help you in battle, the damage they receive will partly transfer to the Boss.",
  str_guide_circle_paotai_LtT = "Agile Turret",
  str_guide_circle_paotai_Lt = "A high-performance turret. Even though it requires manual operation, it's potentially more effective than automated ones.",
  str_guide_circle_paotai_RtT = "Trap Characteristics",
  str_guide_circle_paotai_Rt = "Tap the trap and spend 2 Force Points to launch 1 attack, inflicting damage and debuffs on the enemies in a straight line ahead.",
  str_guide_circle_fengchuan_RtT = "Trap Characteristics",
  str_guide_circle_fengchuan_Rt = "Becomes even more portable and easy to use, able to release skills by consuming the team's Force Points.",
  str_guide_circle_8024001 = "In Purging Evil in the Still Night, the team no longer moves according to the original rules but consumes Force Points for movement.",
  str_guide_circle_8024002 = "The player's current Force Points are displayed on the left, where real-time previews of remaining Force Points are available during tile connections.",
  str_guide_circle_8024003 = "The movement earlier seems to have depleted your Force Points. But don't worry; you will receive a certain amount of Force Points at the start of each round, and the next round's replenishment will be displayed on the far right.",
  str_guide_circle_8024004 = "Tap here to view the currently active talent effects.",
  str_guide_circle_8024005 = "Force Points not consumed each round won't vanish at the round's end. Sometimes, it can be a wise choice to save a round's Force Points.",
  str_guide_season_talent_tree_1 = "Knack Selection is composed of several Formation Nodes and Knacks and grants additional bonuses. Let's start by activating the first Formation Node!",
  str_guide_season_talent_tree_2 = "Tap Activate to consume Auspicious Energy to activate the first Formation Node.",
  str_guide_season_talent_tree_3 = "Once a Formation Node is activated, its effects will start to take effect in battles. It's also possible to unlock Knack slots in some Formation Nodes.",
  str_guide_season_talent_tree_4 = "Now let's try to activate and equip the first Passive Skill. Please tap this Passive Skill.",
  str_guide_season_talent_tree_5 = "Tap Activate to consume Auspicious Energy and activate this Knack.",
  str_guide_season_talent_tree_6 = "After activating the Knack, drag it to the corresponding Knack slot to equip it and use its effect in battle.",
  str_guide_season_talent_tree_7 = "Skill slots have certain Skill type restrictions. The first Skill slot can only be equipped with a Caelestite Skill, and other slots can only be equipped with Passive Skills.",
  str_guide_season_talent_tree_8 = "Please view the gameplay info for more details about the rules.",
  str_guide_season_trade_out_1 = "Daytime Merchant is a new gameplay in which Navigators can manage a port and ships to earn Working Capital and Auspicious Energy.",
  str_guide_season_trade_out_2 = "Purging Evil in the Still Night is a new gameplay with linear stages. In this gameplay, Navigators will move according to a new system and use Feng Shui Knacks to gain advantages in battle!",
  str_guide_season_trade_in_1 = "Navigators will need to manage harbors and ships and can tap Renovation Upgrade in the upper right corner to upgrade the selected target.",
  str_guide_season_trade_in_2 = "Harbor and ship levels will affect harbor unloading speed, remaining load of ships, and the time required to unload goods after completing voyages.",
  str_guide_season_trade_in_3 = "Hired crew members can be assigned to various ships, but each crew member can only be assigned to one ship at a time.",
  str_guide_season_trade_in_4 = "Crew members have Dispatch, Shipping Capacity, and Readiness attributes. Upgrade harbors to hire more capable crew members.",
  str_guide_season_trade_in_5 = "The Ship Status of each ship is determined by the Ability Points of the crew members assigned to the ship. If a ship doesn't meet the ship level requirements, its Ship Status will be significantly lower, which will affect its profit.",
  str_guide_season_trade_in_6 = "Meet the various Working Capital stage targets of voyages to upgrade the Guild Prosperity Level and claim additional rewards!",
  str_guide_season_trade_in_7 = "Try hard to upgrade the harbors and ships, assign suitable crew members to ships, and respond appropriately to sailing incidents to earn more profit from voyages!",
  str_guide_season_trade_in_8 = "Please view the gameplay info for more details about the rules.",
  str_guide_mouse_Rt = "Small-sized omnivorous fiendlings with insufficient cultivation, keeping a wild nature. They always sneak into Aurorian dwellings to steal food. Some aggressive ones may even cause harm.",
  str_guide_mouse_RtT = "Fiendling: Rat",
  str_guide_mouse_Lt = "Nimble and quick, it swiftly moves behind the target after an attack.",
  str_guide_mouse_LtT = "Enemy Characteristics",
  str_guide_mouse_Lb = "Targets the Aurorian with the lowest DEF in the team when attacking, dealing damage. Try to avoid deploying Aurorians with low DEF into battle.",
  str_guide_mouse_LbT = "Coping Strategy",
  str_guide_circle_2909301_Lt = "Legend has it that on the eve of Spring Festival, a fierce beast-like fiendling descends upon Longzhou, causing chaos. Those who successfully expel it are blessed with a whole year of peace and good fortune.",
  str_guide_circle_2909301_LtT = "Fiendling: Nian",
  str_guide_circle_2909301_Rt = "Cast Active Skills to frighten the Nian, slowing its advance.",
  str_guide_circle_2909301_RtT = "Coping Strategy",
  str_guide_circle_2909301_Lb = "Leaps forward and deals damage, making 1 surrounding cluster impassable. If Nian destroys the gate, the battle ends in defeat.",
  str_guide_circle_2909301_LbT = "Enemy Characteristics",
  str_guide_circle_80050001_Rt = "Gains 10 points of Combat Energy at the start of each round. Grants ATK boost to all monsters on the field if there are more than 30 energy points at the end of the round.",
  str_guide_circle_80050001_RtT = "Intel Eclipsite - Courier",
  str_guide_circle_80050001_Rb = "When Aurorians deal damage to the Courier with Active Skills and Normal Attacks, they can diminish its Combat Energy. The Courier inflicts damage on all monsters on the field upon elimination.",
  str_guide_circle_80050001_RbT = "Coping Strategy",
  str_guide_warn_80050111 = "Navigator, look over here! You've gained a new ability in the Dream!",
  str_guide_warn_80050112 = "Your abilities will get stronger as you venture deeper into dreams. Make good use of them!",
  str_guide_circle_80150101 = "The team no longer moves according to the original rules but consumes Force Points for movement, regardless of tile color.",
  str_guide_circle_80150102 = "Displayed here are the player's Force Points, listed from left to right as Current Force Points, Maximum Storage, and Force Point Recovery.",
  str_guide_circle_80150103 = "At the start of each round, players automatically restore Force Points based on the amount displayed in Force Point Recovery, which increases with each round.",
  str_guide_circle_80150201 = "In this gameplay, players recover 1 Force Point for every Dark Tile consumed.",
  str_guide_circle_80150301 = "Tap to select a Rock and consume Force Points to clear it.",
  str_guide_circle_80250101 = "In this gameplay, when players unleash Chain Combo skills, Dark Tiles are considered as 2 tiles for consumption.",
  str_guide_circle_2921201_Lt = "The captain of the Silent Hunters has now turned his blade at the very teammates who always trust him... This is how much he has compromised with the kingdom.",
  str_guide_circle_2921201_LtT = "Claymore",
  str_guide_circle_2921201_Rt = "Based on battlefield conditions, Claymore can choose to move by connecting tiles and then attacking, or launching a Double Strike after a regular movement. As HP drops, he can unleash special skills to carve up the battlefield, battling opponents in a more confined space.",
  str_guide_circle_2921201_RtT = "Enemy Characteristics",
  str_guide_circle_2921201_Lb = "Make sure not to get hit by special skills; the rest is up to your capabilities.",
  str_guide_circle_2921201_LbT = "Coping Strategy",
  str_guide_circle_2909401_Lt = "An enigmatic and formidable Wraith, traversing the lands for training. His breath exudes terror, foretelling doom for those who incur his wrath.",
  str_guide_circle_2909401_LtT = "Ira",
  str_guide_circle_2909401_Rt = "Able to summon Shadowfire with Darkflow in battle.",
  str_guide_circle_2909401_RtT = "Enemy Characteristics",
  str_guide_circle_2909401_Lb = "Note: Ira's Darkflow Meteorite, composed of raging flames, can instantly kill Aurorians within its range. Pay attention to warning areas and dodge promptly!",
  str_guide_circle_2909401_LbT = "Coping Strategy",
  str_guide_n43_1 = [[
Glimmers of Light is now available!
Let's start a new story in the Second Interlude!]],
  str_guide_n43_2 = "Story chapters that are unlocked in this event, as well as chapters that have been explored so far, are displayed here.",
  str_guide_n43_3 = "Tap Explore Now to go directly to the Explore map. Spend Prism in main story stages and Resource Raid stages for Caelestite Feathers.",
  str_guide_n43_4 = "In Aurora Exchange, use Caelestite Feathers to redeem various rewards.",
  str_guide_n43_5 = "Participate in event story stages to complete quests in your Special Event Book!",
  str_guide_n43_6 = "Remember to log into the game every day to get Navigation Sign-In rewards.",
  str_guide_n43_7 = "If you have any questions about the event, you can view the detailed description here.",
  str_guide_warn_90010702 = "Notice: Tap here to open the Dream Orb screen.",
  str_guide_warn_90010703 = "Notice: There are multiple slots on the Enlightenment Spiral. Place the Dream Orb into an empty slot to analyze it and unleash its power.",
  str_guide_warn_90010704 = "Notice: Tap on the Dream Orb to view its details.",
  str_guide_warn_90010705 = "Notice: Tap the Equip button to place the Dream Orb into the Enlightenment Spiral. You can also drag the Dream Orb directly into an empty slot.",
  str_guide_warn_90010706 = "Commentary: Sufficient energy is needed to unleash the power of the Dream Orbs on the Enlightenment Spiral. But don't worry; as your Enlightener, I believe you can accumulate enough energy in battle.",
  str_guide_warn_90010707 = "Notice: If you possess multiple Dream Orbs, consider merging them to acquire higher-level Dream Orbs.",
  str_guide_warn_90010708 = "Two Dream Orbs of the same level can be synthesized into 1 Dream Orb that is 1 level higher.",
  str_guide_warn_90010709 = "Notice: If you have any questions, you can view the detailed description here.",
  str_guide_circle_2004901_LbT = "Haze",
  str_guide_circle_2004901_Lb = "Formed from the rapid accumulation of Darkflow around dead enemies. Be careful! The anger and resentment of your enemies live on inside it.",
  str_guide_circle_2004901_RtT = "Enemy Characteristics",
  str_guide_circle_2004901_Rt = [[
All damage it takes is reduced to 1. It can't attack but will keep moving towards Aurorians.
Haze is not counted for wave refresh and stage victory conditions.]],
  str_guide_circle_2004901_RbT = "Coping Strategy",
  str_guide_circle_2004901_Rb = "Haze disappears immediately upon being knocked back, pulled over, or forced to move. It disappears normally after a certain number of rounds.",
  str_guide_circle_80060313_LbT = "Elite Affix: Haze",
  str_guide_circle_80060313_Lb = [[
Enemies that have this elite affix will generate Haze upon death, with the quantity generated determined by the size of the enemy.
Tap on the enemy to view more details.]],
  str_guide_circle_2909501_LbT = "Carrot: Blight",
  str_guide_circle_2909501_Lb = "After absorbing too much resentment in a dark place and rotting, this carrot has expanded into a bizarre creature that seeks revenge after gaining the power of Darkflow.",
  str_guide_circle_2909501_RtT = "Enemy Characteristics",
  str_guide_circle_2909501_Rt = "Throws carrots, dealing multiple instances of damage. When rotating at high speed, it deals multiple instances of damage to enemies in a large area and knocks them back.",
  str_guide_circle_2909501_RbT = "Coping Strategy",
  str_guide_circle_2909501_Rb = "This enemy is quite big. Deploy Detonator Aurorians to defeat it!",
  str_guide_circle_2909502_LbT = "Carrot: Blight",
  str_guide_circle_2909502_Lb = "After absorbing too much resentment in a dark place and rotting, this carrot has expanded into a bizarre creature that seeks revenge after gaining the power of Darkflow.",
  str_guide_circle_2909502_RtT = "Enemy Characteristics",
  str_guide_circle_2909502_Rt = [[
Throws carrots, dealing multiple instances of damage. When rotating at high speed, it deals multiple instances of damage to enemies in a large area and knocks them back.
In emergencies, it can shrink and burrow into the ground and continue fighting from there.]],
  str_guide_circle_2909502_RbT = "Coping Strategy",
  str_guide_circle_2909502_Rb = [[
This enemy is quite big. Deploy Detonator Aurorians to defeat it!
Note: This enemy transforms into its 4-tile form when it is invincible!]],
  str_guide_circle_80060101_RtT = "Dream Bleeding",
  str_guide_circle_80060101_Rt = "A unique aspect of the current Dream that turns all Bleeding effects into Wounded effects. Anything that triggers Bleeding effects will also trigger Wounded effects.",
  str_guide_circle_80060101_RbT = "Wounded Mechanics",
  str_guide_circle_80060101_Rb = "While Wounded, enemies take damage every round based on the average ATK of the Aurorian team. The higher the Aurorian team's HP percentage, the more Wounded stacks that can be applied, and the more damage that can be dealt. Wounded stacks up to 5 times, and doesn't disappear when the round ends.",
  str_guide_circle_80060102_LtT = "Wounded Status",
  str_guide_circle_80060102_Lt = "Enemies in the early stages will start with 1 Wounded stack by default, and take Wounded damage every round. Tap an enemy to view its Wounded effects.",
  str_guide_circle_80060201_RtT = "Explosive Pebble",
  str_guide_circle_80060201_Rt = "A seemingly ordinary, yet highly explosive pebble. Upon it is destroyed, deals damage to all nearby enemies and inflicts 1 Wounded stack.",
  str_guide_circle_80060201_LtT = "Spreading Blast",
  str_guide_circle_80060201_Lt = "Some pebbles are surprisingly durable and will only detonate after being struck multiple times, which increases their blast radius by 1 tile for every Count HP they have.",
  str_guide_circle_80060401_RtT = "Altered Spikeneedle",
  str_guide_circle_80060401_Rt = "A familiar-looking Spikepest that no longer poses a threat to Aurorians. At the end of each round, it damages and inflicts 1 Wounded stack on all enemies caught in its spikes.",
  str_guide_circle_2909701_LbT = "Insatiable Magmite",
  str_guide_circle_2909701_Lb = "An aberrant type of Eclipsite that uses both lava and Darkflow to deal damage.",
  str_guide_circle_2909701_RtT = "Enemy Characteristics",
  str_guide_circle_2909701_Rt = "Can deal damage in a large area, as well as summon a molten shield to protect itself.",
  str_guide_circle_2909701_RbT = "Coping Strategy",
  str_guide_circle_2909701_Rb = "While protected by its molten shield, Insatiable Magmite reflects all incoming normal attacks. Make sure to keep an eye out for Earthfire eruptions from the ground!",
  str_guide_warn_811400101 = "During the Deadly Omens event, you can challenge different Omens that will gradually unlock over time.",
  str_guide_warn_811400102 = "Tap an Omen to go to the challenge interface.",
  str_guide_warn_811400103 = "Each Omen has three difficulty levels. Here, you can choose freely between them.",
  str_guide_warn_811400104 = "This is where you can view the battlefield conditions and learn more about the attributes of the Omen's boss.",
  str_guide_warn_811400105 = "In each Omen, you can choose one to three enhancement effects to make you stronger. The higher the difficulty, the more enhancement effects you can select.",
  str_guide_warn_811400106 = "Tap on a slot to select an enhancement effect.",
  str_guide_warn_811400107 = "Each enhancement effect is divided into 3 areas, and each area must be unlocked in order from top to bottom.",
  str_guide_warn_811400108 = "Tap on a box to select the corresponding enhancement effect.",
  str_guide_warn_811400109 = "Tap to confirm and save the selected enhancement effects.",
  str_guide_warn_811400110 = "Clear the stages to complete challenge missions and claim great rewards.",
  str_guide_circle_2909801_LbT = "Spearhead: Rotbone Stinger",
  str_guide_circle_2909801_Lb = "Once a battle Colossus who charged headfirst into the fray in the name of the Eclipse, it is now just a shattered pile of rubble, its last remaining threat lying in its tailbone.",
  str_guide_circle_2909801_RtT = "Enemy Characteristics",
  str_guide_circle_2909801_Rt = "Capable of dealing damage to targets in a large area and generating peripheral units that move in a cluster formation to block Aurorians.",
  str_guide_circle_2909801_RbT = "Coping Strategy",
  str_guide_circle_2909801_Rb = "Constantly summons peripheral units to defend itself. Avoid them to deal damage to them.",
  str_guide_2005101_Rt = "Originally a part of Spearhead's tail, these pieces broke off one by one and scattered throughout the underground ruins.",
  str_guide_2005101_RtT = "Periphery Provocant",
  str_guide_2005101_Lt = "Flying monsters controlled by a mysterious force, constantly form strange formations to launch close-range attacks on intruders.",
  str_guide_2005101_LtT = "Enemy Characteristics",
  str_guide_2005101_Lb = "Peripheral units can quickly surround their targets. Destroy them at their joints as soon as possible to prevent this.",
  str_guide_2005101_LbT = "Coping Strategy",
  str_guide_2910001_Lt = "Can attack Aurorians with various body parts. Damaging any part of Syurton will harm it.",
  str_guide_2910001_LtT = "Enemy Characteristics",
  str_guide_2910001_Lb = "Dodge attacks and try to hit multiple parts at once!",
  str_guide_2910001_LbT = "Coping Strategy",
  str_guide_2910002_Lt = "Can attack Aurorians with various body parts. Damaging any part of Syurton will harm it.",
  str_guide_2910002_LtT = "Enemy Characteristics",
  str_guide_2910002_Lb = "Beware! Syurton's tail only takes single-target damage!",
  str_guide_2910002_LbT = "Coping Strategy",
  str_guide_circle_2910101_Lb = "Head of the Porfirio family. He is someone who likes dominating others and relentlessly pursues power by any means.",
  str_guide_circle_2910101_LbT = "David Porfirio",
  str_guide_circle_2910101_Rt = "When Sanity is 50 or higher, summons Necroservant minions. When below 50, attacks Aurorians to restore its own HP and summon Necroservants.",
  str_guide_circle_2910101_RtT = "Enemy Characteristics",
  str_guide_circle_2910101_Rb = "Manage Sanity and respond to David Porfirio's threats based on the situation.",
  str_guide_circle_2910101_RbT = "Coping Strategy",
  str_guide_circle_2005201_Lb = "Miserable departed souls, forever deceived and confined. Now they wander, seeking fresh warm blood for their master.",
  str_guide_circle_2005201_LbT = "Necroservant",
  str_guide_circle_2005201_Rt = "When Sanity is 50 or higher, drains Aurorians' Sanity. When below 50, attacks Aurorians.",
  str_guide_circle_2005201_RtT = "Enemy Characteristics",
  str_guide_circle_2005201_Rb = "Manage Sanity and respond to Necroservants' threats based on the situation.",
  str_guide_circle_2005201_RbT = "Coping Strategy",
  str_guide_2909901_LtT = "Stone Giant of the Ruins",
  str_guide_2909901_Lt = "In the eyes of future Aurorians, extraordinary advanced technology may be seen as equivalent to magic, and in Fleur's eyes, the stone giant is akin to a mecha.",
  str_guide_2909901_LbT = "Enemy Characteristics",
  str_guide_2909901_Lb = "Possesses powerful healing abilities.",
  str_guide_2909901_RbT = "Coping Strategy",
  str_guide_2909901_Rb = "Expertly utilize alchemy materials and adjust your distance to deal with it.",
  str_guide_2803101_LbT = "Alchemy Material",
  str_guide_2803101_Lb = "When picked up, increases Tactical Points for the Tactical System. It is also a victory condition for certain battle stages.",
  str_guide_2910201_LtT = "Stellandine: Prototype",
  str_guide_2910201_Lt = "Cloaked in disguise, it sings and cries to lure in its prey. Once the disguise is shed, it defeats its enemies with violence and poison. All along, it fails to understand that love is suppressing one's nature.",
  str_guide_2910201_LbT = "Enemy Characteristics",
  str_guide_2910201_Lb = "Summons a large number of supporting Eclipsites, posing a threat to enemy units around itself.",
  str_guide_2910201_RbT = "Coping Strategy",
  str_guide_2910201_Rb = "Control the number of Eclipsites and defeat the boss as soon as possible.",
  str_guide_2005301_LtT = "Salvo Gun",
  str_guide_2005301_Lt = "It's learning about Aurorians but having a hard time understanding when to fire the gun salute. All she wants is to whisper tenderly, but she ends up becoming a deep sea poison that corrodes everyone who approaches.",
  str_guide_2005301_LbT = "Enemy Characteristics",
  str_guide_2005301_Lb = "Deals damage to enemy units within 1 surrounding cluster every round.",
  str_guide_2005401_LtT = "Demand",
  str_guide_2005401_Lt = "Hungry for physical contact and love, it constantly approaches Aurorians. Afraid of getting hurt and being hated, it'd rather strike first.",
  str_guide_2005401_LbT = "Enemy Characteristics",
  str_guide_2005401_Lb = "When there is an Aurorian within 2 clusters of itself, it summons an Eclipsite near the target to assist itself.",
  str_guide_circle_82910301_RtT = "Enemy Characteristics",
  str_guide_circle_82910301_Rt = "Adept at using mirrors to outmaneuver enemies, avoiding damage while delivering deadly strikes. The true form is immune to skill damage, and the mirror image is immune to physical damage.",
  str_guide_circle_82910301_LbT = "Nepolis",
  str_guide_circle_82910301_Lb = "Nikinis's Sister",
  str_guide_circle_82910301_RbT = "Coping Strategy",
  str_guide_circle_82910301_Rb = "Choose your targets wisely to deal effective damage, and plan your movement path to outmaneuver them."
}
return config
